-- Baby daily texts: fix broken and misaligned translations (owner request 2026-11-12, translation alignment audit).
-- Days 1096-1100: the Azerbaijani source and every translation held a "[[TRANSLATION FAILED]]" placeholder; new
--   Azerbaijani texts (language, kindergarten, 3-year tantrums, cognitive development, WHO weight/height at 3 years)
--   and their 20 translations.
-- Days 246 and 387: en, zh, id, fr, es, pt, vi, hi, ja, ko, pl, nl, sv held another day's text (days 606 / 462);
--   re-translated from the Azerbaijani text.
-- Each update applies only if the row is unchanged since the audit (md5); the final check rolls back otherwise.
-- baby_daily_info is already CDC enrolled and writer guarded. Applied with run-sql.py.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM _anacan_gcp_migration.guarded_relations WHERE schema_name = 'public' AND table_name = 'baby_daily_info') THEN
    RAISE EXCEPTION 'BABY_TEXT_FIX_GUARD_MISSING'; END IF;
END $$;

UPDATE public.baby_daily_info SET info = 'Övladınızın dil bacarıqları bu dövrdə sürətlə inkişaf edir. 3 yaşına çatan uşaqların çoxu 3-4 sözdən ibarət cümlələr qurur, adını və yaşını deyə bilir, "mən", "sən", "biz" kimi əvəzlikləri düzgün işlədir. Söz ehtiyatı artıq yüzlərlə sözdən ibarətdir və hər gün yeni sözlər öyrənir. Ailə üzvləri dediklərinin böyük hissəsini anlamalı, tanımadığı insanlar da çox vaxt onu başa düşməlidir. Bəzi səsləri, məsələn, "r" və "ş" səslərini hələ düzgün tələffüz etməyə bilər, bu, bu yaş üçün normaldır. Dil inkişafını dəstəkləmək üçün onunla gün ərzində bol-bol danışın, suallarına səbirlə cavab verin, birlikdə kitab oxuyub şəkillər haqqında söhbət edin. Səhv tələffüz etdiyi sözü düzəltmək əvəzinə, həmin sözü düzgün formada təkrarlayın. Əgər övladınız 2-3 sözlük cümlələr qura bilmirsə, sadə tapşırıqları anlamırsa və ya danışığını ailə üzvləri də çətinliklə başa düşürsə, uşaq həkimi ilə məsləhətləşin.', info_en = 'Your child''s language skills are developing rapidly at this stage. Most children who turn 3 form sentences of 3-4 words, can say their name and age, and use pronouns such as "I", "you" and "we" correctly. Their vocabulary already includes hundreds of words, and they learn new ones every day. Family members should understand most of what they say, and even people who don''t know them should usually be able to understand them. They may not yet pronounce some sounds correctly, such as "r" and "sh", and this is normal at this age. To support their language development, talk with them a lot throughout the day, answer their questions patiently, and read books together while chatting about the pictures. Instead of correcting a word they mispronounce, simply repeat it back in its correct form. If your child cannot form 2-3 word sentences, does not understand simple instructions, or if even family members have difficulty understanding their speech, consult a pediatrician.', info_ru = 'В этот период речевые навыки вашего ребёнка стремительно развиваются. Большинство детей к 3 годам строят предложения из 3-4 слов, могут назвать своё имя и возраст, правильно используют местоимения «я», «ты», «мы». Словарный запас уже насчитывает сотни слов, и каждый день ребёнок узнаёт новые. Члены семьи должны понимать большую часть того, что он говорит, а незнакомые люди тоже чаще всего должны его понимать. Некоторые звуки, например «р» и «ш», он может пока произносить неправильно, и для этого возраста это нормально. Чтобы поддержать развитие речи, побольше разговаривайте с ним в течение дня, терпеливо отвечайте на его вопросы, читайте вместе книги и обсуждайте картинки. Вместо того чтобы исправлять неправильно произнесённое слово, повторите его в правильной форме. Если ваш ребёнок не может строить предложения из 2-3 слов, не понимает простых просьб или даже члены семьи с трудом понимают его речь, проконсультируйтесь с педиатром.', info_tr = 'Çocuğunuzun dil becerileri bu dönemde hızla gelişir. 3 yaşına gelen çocukların çoğu 3-4 kelimelik cümleler kurar, adını ve yaşını söyleyebilir, "ben", "sen", "biz" gibi zamirleri doğru kullanır. Kelime dağarcığı artık yüzlerce kelimeden oluşur ve her gün yeni kelimeler öğrenir. Aile üyeleri söylediklerinin büyük bölümünü anlamalı, tanımadığı kişiler de çoğu zaman onu anlayabilmelidir. Bazı sesleri, örneğin "r" ve "ş" seslerini henüz doğru telaffuz edemeyebilir; bu, bu yaş için normaldir. Dil gelişimini desteklemek için gün boyunca onunla bolca konuşun, sorularını sabırla yanıtlayın, birlikte kitap okuyup resimler hakkında sohbet edin. Yanlış telaffuz ettiği kelimeyi düzeltmek yerine, o kelimeyi doğru biçimde tekrarlayın. Çocuğunuz 2-3 kelimelik cümleler kuramıyorsa, basit yönergeleri anlamıyorsa veya konuşmasını aile üyeleri bile güçlükle anlıyorsa çocuk doktorunuza danışın.', info_kk = 'Бұл кезеңде балаңыздың тілдік дағдылары қарқынды дамиды. 3 жасқа толған балалардың көбі 3-4 сөзден тұратын сөйлем құрайды, өз атын және жасын айта алады, «мен», «сен», «біз» сияқты есімдіктерді дұрыс қолданады. Сөздік қоры қазір жүздеген сөзден тұрады және ол күн сайын жаңа сөздер үйренеді. Отбасы мүшелері оның айтқанының басым бөлігін түсінуі керек, ал бөгде адамдар да көбіне оны түсінуі тиіс. Кейбір дыбыстарды, мысалы, «р» және «ш» дыбыстарын ол әлі дұрыс айта алмауы мүмкін, бұл осы жас үшін қалыпты жағдай. Тілдің дамуына қолдау көрсету үшін күн бойы онымен көп сөйлесіңіз, сұрақтарына сабырмен жауап беріңіз, бірге кітап оқып, суреттер туралы әңгімелесіңіз. Ол қате айтқан сөзді түзетудің орнына, сол сөзді дұрыс түрде қайталап айтыңыз. Егер балаңыз 2-3 сөзден тұратын сөйлем құрай алмаса, қарапайым тапсырмаларды түсінбесе немесе оның сөзін отбасы мүшелерінің өзі әрең түсінсе, балалар дәрігерімен кеңесіңіз.', info_de = 'Die sprachlichen Fähigkeiten deines Kindes entwickeln sich in dieser Phase rasant. Die meisten Kinder bilden mit 3 Jahren Sätze aus 3-4 Wörtern, können ihren Namen und ihr Alter sagen und verwenden Pronomen wie „ich“, „du“ und „wir“ richtig. Der Wortschatz umfasst bereits Hunderte von Wörtern, und jeden Tag kommen neue hinzu. Familienmitglieder sollten das meiste von dem verstehen, was dein Kind sagt, und auch fremde Menschen sollten es oft verstehen können. Manche Laute, zum Beispiel „r“ oder „sch“, spricht es vielleicht noch nicht richtig aus. Das ist in diesem Alter normal. Um die Sprachentwicklung zu fördern, sprich im Laufe des Tages viel mit deinem Kind, beantworte seine Fragen geduldig, lest gemeinsam Bücher und unterhaltet euch über die Bilder. Statt ein falsch ausgesprochenes Wort zu korrigieren, wiederhole es einfach in der richtigen Form. Wenn dein Kind keine Sätze aus 2-3 Wörtern bilden kann, einfache Aufforderungen nicht versteht oder selbst Familienmitglieder es nur schwer verstehen, sprich mit deiner Kinderärztin oder deinem Kinderarzt.', info_ar = 'تتطور المهارات اللغوية لطفلكِ بسرعة في هذه المرحلة. فمعظم الأطفال عند بلوغ 3 سنوات يكوّنون جملًا من 3-4 كلمات، ويستطيعون قول أسمائهم وأعمارهم، ويستخدمون الضمائر مثل «أنا» و«أنتَ» و«نحن» بشكل صحيح. وأصبحت حصيلته اللغوية تضم مئات الكلمات، ويتعلم كلمات جديدة كل يوم. ومن المتوقع أن يفهم أفراد العائلة معظم ما يقوله، وأن يفهمه الغرباء أيضًا في كثير من الأحيان. وقد لا يتمكن بعد من نطق بعض الأصوات بشكل صحيح، مثل صوتي «ر» و«ش»، وهذا أمر طبيعي في هذا العمر. ولدعم تطوره اللغوي، تحدّثي معه كثيرًا على مدار اليوم، وأجيبي عن أسئلته بصبر، واقرئي معه الكتب وتحدّثا معًا عن الصور. وبدلًا من تصحيح الكلمة التي ينطقها بشكل خاطئ، كرّريها أمامه بصيغتها الصحيحة. وإذا كان طفلكِ لا يستطيع تكوين جمل من 2-3 كلمات، أو لا يفهم التعليمات البسيطة، أو كان أفراد العائلة أنفسهم يجدون صعوبة في فهم كلامه، فاستشيري طبيب الأطفال.', info_uz = 'Farzandingizning nutq ko‘nikmalari bu davrda tez rivojlanadi. 3 yoshga to‘lgan bolalarning ko‘pchiligi 3-4 so‘zdan iborat gaplar tuzadi, o‘z ismi va yoshini ayta oladi, «men», «sen», «biz» kabi olmoshlarni to‘g‘ri ishlatadi. Uning so‘z boyligi allaqachon yuzlab so‘zlardan iborat va har kuni yangi so‘zlarni o‘rganadi. Oila a’zolari uning gaplarining katta qismini tushunishi, notanish odamlar ham ko‘pincha uni tushuna olishi kerak. Ayrim tovushlarni, masalan, «r» va «sh» tovushlarini hali to‘g‘ri talaffuz qila olmasligi mumkin, bu yoshda bu odatiy holdir. Nutq rivojlanishini qo‘llab-quvvatlash uchun kun davomida u bilan ko‘proq gaplashing, savollariga sabr bilan javob bering, birga kitob o‘qib, rasmlar haqida suhbatlashing. Noto‘g‘ri talaffuz qilgan so‘zini tuzatish o‘rniga, o‘sha so‘zni to‘g‘ri shaklda takrorlang. Agar farzandingiz 2-3 so‘zli gaplar tuza olmasa, oddiy topshiriqlarni tushunmasa yoki uning nutqini oila a’zolari ham qiyinchilik bilan tushunsa, pediatr bilan maslahatlashing.', info_ka = 'ამ პერიოდში თქვენი ბავშვის მეტყველების უნარები სწრაფად ვითარდება. 3 წლის ასაკში ბავშვების უმეტესობა 3-4 სიტყვისგან შემდგარ წინადადებებს აგებს, შეუძლია თქვას თავისი სახელი და ასაკი და სწორად იყენებს ნაცვალსახელებს, როგორიცაა „მე“, „შენ“, „ჩვენ“. მისი ლექსიკური მარაგი უკვე ასობით სიტყვას მოიცავს და ყოველდღე ახალ სიტყვებს სწავლობს. ოჯახის წევრებს მისი ნათქვამის დიდი ნაწილი უნდა ესმოდეთ, ხოლო უცნობ ადამიანებსაც ხშირად უნდა ესმოდეთ მისი. ზოგიერთ ბგერას, მაგალითად, „რ“-სა და „შ“-ს, შესაძლოა ჯერ კიდევ სწორად ვერ წარმოთქვამდეს, რაც ამ ასაკისთვის ნორმალურია. მეტყველების განვითარების ხელშესაწყობად დღის განმავლობაში ბევრი ესაუბრეთ, მოთმინებით უპასუხეთ მის კითხვებს, ერთად იკითხეთ წიგნები და ისაუბრეთ სურათებზე. არასწორად წარმოთქმული სიტყვის გასწორების ნაცვლად, უბრალოდ გაიმეორეთ ეს სიტყვა სწორი ფორმით. თუ ბავშვს არ შეუძლია 2-3 სიტყვიანი წინადადებების აგება, ვერ იგებს მარტივ დავალებებს ან მის მეტყველებას ოჯახის წევრებიც კი ძლივს იგებენ, მიმართეთ პედიატრს.', info_zh = '这个阶段，您孩子的语言能力发展迅速。大多数满3岁的孩子能说出由3-4个词组成的句子，能说出自己的名字和年龄，并能正确使用“我”“你”“我们”等代词。孩子的词汇量已经达到数百个，而且每天都在学习新词。家人应该能听懂孩子说的大部分话，不认识的人通常也应该能听懂。孩子可能还不能准确发出某些音，比如“r”“sh”这样的卷舌音，这在这个年龄是正常的。为了促进语言发展，请在一天中多和孩子聊天，耐心回答孩子的问题，一起读书并聊聊书里的图画。孩子说错某个词时，不要直接纠正，而是用正确的方式把这个词再说一遍。如果孩子还不能说出2-3个词的句子、听不懂简单的指令，或者连家人都很难听懂孩子说的话，请咨询儿科医生。', info_id = 'Kemampuan berbahasa anak Anda berkembang pesat pada masa ini. Sebagian besar anak usia 3 tahun sudah dapat menyusun kalimat yang terdiri dari 3-4 kata, menyebutkan nama dan usianya, serta menggunakan kata ganti seperti "aku", "kamu", dan "kita" dengan benar. Kosakatanya sudah mencapai ratusan kata, dan setiap hari ia mempelajari kata-kata baru. Anggota keluarga seharusnya memahami sebagian besar ucapannya, dan orang yang belum mengenalnya pun biasanya sudah dapat memahaminya. Ia mungkin belum dapat mengucapkan beberapa bunyi dengan tepat, misalnya bunyi "r" dan "s", dan hal ini normal pada usia ini. Untuk mendukung perkembangan bahasanya, ajak si Kecil banyak berbicara sepanjang hari, jawab pertanyaannya dengan sabar, serta bacalah buku bersama sambil membicarakan gambar-gambarnya. Daripada mengoreksi kata yang ia ucapkan dengan keliru, ulangi kata tersebut dalam bentuk yang benar. Jika anak Anda belum dapat menyusun kalimat 2-3 kata, tidak memahami perintah sederhana, atau ucapannya sulit dipahami bahkan oleh anggota keluarga, konsultasikan dengan dokter anak.', info_fr = 'Les compétences langagières de votre enfant se développent rapidement à cette période. À 3 ans, la plupart des enfants construisent des phrases de 3-4 mots, savent dire leur prénom et leur âge et utilisent correctement des pronoms comme « je », « tu » et « nous ». Son vocabulaire compte déjà plusieurs centaines de mots, et il en apprend de nouveaux chaque jour. Les membres de la famille devraient comprendre la plus grande partie de ce qu’il dit, et les personnes qui ne le connaissent pas devraient elles aussi le comprendre la plupart du temps. Il est possible qu’il ne prononce pas encore correctement certains sons, comme le « r » ou le « ch » : c’est normal à cet âge. Pour soutenir son développement langagier, parlez-lui beaucoup tout au long de la journée, répondez patiemment à ses questions, lisez des livres ensemble et discutez des images. Au lieu de corriger un mot qu’il prononce mal, répétez-le simplement sous sa forme correcte. Si votre enfant n’arrive pas à former des phrases de 2-3 mots, ne comprend pas des consignes simples ou si même les membres de la famille ont du mal à le comprendre, consultez votre pédiatre.', info_es = 'Las habilidades lingüísticas de tu peque se desarrollan rápidamente en esta etapa. A los 3 años, la mayoría de los niños forman frases de 3-4 palabras, saben decir su nombre y su edad y usan correctamente pronombres como «yo», «tú» y «nosotros». Su vocabulario ya incluye cientos de palabras, y cada día aprende otras nuevas. Los miembros de la familia deberían entender la mayor parte de lo que dice, y las personas que no lo conocen también deberían entenderle casi siempre. Es posible que todavía no pronuncie bien algunos sonidos, como la «r» o la «rr»; es normal a esta edad. Para apoyar el desarrollo de su lenguaje, habla mucho con tu peque a lo largo del día, responde con paciencia a sus preguntas, leed libros juntos y comentad las imágenes. En lugar de corregir una palabra que pronuncia mal, repítela tú de la forma correcta. Si tu peque no es capaz de formar frases de 2-3 palabras, no entiende instrucciones sencillas o incluso a la familia le cuesta entender lo que dice, consulta con el pediatra.', info_pt = 'As capacidades linguísticas da criança desenvolvem-se rapidamente nesta fase. Aos 3 anos, a maioria das crianças constrói frases de 3-4 palavras, consegue dizer o nome e a idade e usa corretamente pronomes como «eu», «tu» e «nós». O vocabulário já inclui centenas de palavras e todos os dias aprende palavras novas. Os membros da família devem compreender a maior parte do que diz, e as pessoas que não a conhecem também devem compreendê-la na maioria das vezes. Pode ainda não pronunciar corretamente alguns sons, como o «r» ou o «lh», o que é normal nesta idade. Para apoiar o desenvolvimento da linguagem, fale muito com a criança ao longo do dia, responda às suas perguntas com paciência, leiam livros juntos e conversem sobre as imagens. Em vez de corrigir uma palavra que pronuncia mal, repita-a da forma correta. Se a criança não consegue formar frases de 2-3 palavras, não compreende instruções simples ou se até a família tem dificuldade em perceber o que diz, consulte o pediatra.', info_vi = 'Ở giai đoạn này, khả năng ngôn ngữ của con phát triển rất nhanh. Phần lớn trẻ lên 3 tuổi có thể nói câu gồm 3-4 từ, nói được tên và tuổi của mình, đồng thời dùng đúng các đại từ như “tớ”, “cậu”, “chúng mình”. Vốn từ của con giờ đã lên tới hàng trăm từ và mỗi ngày con lại học thêm từ mới. Các thành viên trong gia đình nên hiểu được phần lớn những gì con nói, và người lạ cũng thường có thể hiểu con. Con có thể vẫn chưa phát âm đúng một số âm, chẳng hạn như âm “r” hay “s”, điều này là bình thường ở độ tuổi này. Để hỗ trợ con phát triển ngôn ngữ, bạn hãy trò chuyện với con thật nhiều trong ngày, kiên nhẫn trả lời các câu hỏi của con, cùng con đọc sách và nói chuyện về các bức tranh. Thay vì sửa lỗi khi con phát âm sai một từ, bạn hãy nhắc lại từ đó theo cách nói đúng. Nếu con chưa thể nói câu 2-3 từ, không hiểu những yêu cầu đơn giản, hoặc ngay cả người trong gia đình cũng khó hiểu con nói gì, bạn hãy tham khảo ý kiến bác sĩ nhi khoa.', info_hi = 'इस समय आपके बच्चे की भाषा क्षमता तेज़ी से विकसित हो रही है। 3 साल की उम्र तक पहुँचने वाले ज़्यादातर बच्चे 3-4 शब्दों के वाक्य बना लेते हैं, अपना नाम और उम्र बता सकते हैं, और “मैं”, “तुम”, “हम” जैसे सर्वनामों का सही इस्तेमाल करते हैं। अब उसकी शब्दावली में सैकड़ों शब्द हैं और वह हर दिन नए शब्द सीखता है। परिवार के सदस्यों को उसकी कही ज़्यादातर बातें समझ आनी चाहिए, और अनजान लोग भी अक्सर उसे समझ पाने चाहिए। हो सकता है कि वह अभी कुछ ध्वनियों, जैसे “र” और “श”, का सही उच्चारण न कर पाए; इस उम्र में यह सामान्य है। भाषा के विकास में मदद के लिए दिन भर उससे खूब बातें करें, धैर्य से उसके सवालों के जवाब दें, और साथ मिलकर किताबें पढ़ें और तस्वीरों के बारे में बात करें। जब वह किसी शब्द का गलत उच्चारण करे, तो उसे टोकने के बजाय वही शब्द सही रूप में दोहराएँ। अगर आपका बच्चा 2-3 शब्दों के वाक्य नहीं बना पाता, सरल निर्देश नहीं समझता, या परिवार के सदस्यों को भी उसकी बात समझने में कठिनाई होती है, तो शिशु रोग विशेषज्ञ से सलाह लें।', info_ja = 'この時期、お子さんの言葉の力はぐんぐん伸びていきます。3歳を迎える子どもの多くは、3-4語からなる文を話し、自分の名前や年齢を言うことができ、「わたし」「あなた」「わたしたち」といった代名詞を正しく使えるようになります。語彙はすでに数百語にのぼり、毎日新しい言葉を覚えています。家族には話していることの大部分が伝わり、知らない人にもたいてい理解してもらえるのが目安です。「ら行」や「さ行」など、一部の音をまだ正しく発音できないこともありますが、この年齢では普通のことです。言葉の発達を促すために、一日を通してたくさん話しかけ、質問には根気よく答え、一緒に絵本を読みながら絵についておしゃべりしましょう。言い間違えた言葉を訂正する代わりに、その言葉を正しい形で言い直してあげてください。お子さんが2-3語の文を話せない、簡単な指示を理解できない、または家族でも話していることを聞き取りにくい場合は、小児科医に相談しましょう。', info_ko = '이 시기에 아이의 언어 능력은 빠르게 발달해요. 3세가 된 아이들 대부분은 3-4개의 단어로 된 문장을 만들고, 자기 이름과 나이를 말할 수 있으며, ''나'', ''너'', ''우리'' 같은 대명사를 올바르게 사용해요. 어휘는 이미 수백 개에 이르고, 매일 새로운 단어를 배워요. 가족은 아이가 하는 말의 대부분을 알아들을 수 있어야 하고, 아이를 모르는 사람도 대개 아이의 말을 이해할 수 있어야 해요. ''ㄹ''이나 ''ㅅ'' 같은 일부 소리는 아직 정확하게 발음하지 못할 수 있는데, 이 나이에는 정상적인 일이에요. 언어 발달을 돕기 위해 하루 동안 아이와 많이 이야기하고, 질문에는 인내심을 갖고 대답해 주며, 함께 책을 읽으면서 그림에 대해 이야기를 나눠 보세요. 아이가 잘못 발음한 단어를 고쳐 주는 대신, 그 단어를 올바른 형태로 다시 말해 주세요. 아이가 2-3개 단어로 된 문장을 만들지 못하거나, 간단한 지시를 이해하지 못하거나, 가족조차 아이의 말을 알아듣기 어렵다면 소아청소년과 의사와 상담하세요.', info_pl = 'Umiejętności językowe Twojego dziecka rozwijają się teraz bardzo szybko. Większość trzylatków buduje zdania złożone z 3-4 słów, potrafi podać swoje imię i wiek oraz poprawnie używa zaimków takich jak „ja”, „ty”, „my”. Słownictwo dziecka obejmuje już setki słów, a każdego dnia poznaje ono nowe. Członkowie rodziny powinni rozumieć większość tego, co mówi, a osoby obce także zwykle powinny je rozumieć. Dziecko może jeszcze nie wymawiać poprawnie niektórych głosek, na przykład „r” i „sz”, co w tym wieku jest normalne. Aby wspierać rozwój mowy, rozmawiaj z dzieckiem jak najczęściej w ciągu dnia, cierpliwie odpowiadaj na jego pytania, czytajcie razem książki i rozmawiajcie o obrazkach. Zamiast poprawiać słowo, które dziecko wymówiło niepoprawnie, powtórz je w prawidłowej formie. Jeśli Twoje dziecko nie potrafi budować zdań złożonych z 2-3 słów, nie rozumie prostych poleceń lub nawet członkowie rodziny z trudem rozumieją jego mowę, skonsultuj się z pediatrą.', info_nl = 'De taalvaardigheid van je kind ontwikkelt zich in deze periode snel. De meeste kinderen van 3 jaar maken zinnen van 3-4 woorden, kunnen hun naam en leeftijd zeggen en gebruiken voornaamwoorden als ‘ik’, ‘jij’ en ‘wij’ op de juiste manier. De woordenschat bestaat inmiddels uit honderden woorden en elke dag komen er nieuwe bij. Gezinsleden zouden het grootste deel van wat je kind zegt moeten begrijpen, en ook onbekenden zouden je kind meestal moeten kunnen verstaan. Sommige klanken, zoals de ‘r’ en de ‘sj’, kan je kind misschien nog niet goed uitspreken; dat is normaal op deze leeftijd. Praat de hele dag veel met je kind om de taalontwikkeling te ondersteunen, beantwoord vragen geduldig en lees samen boekjes terwijl je over de plaatjes praat. Verbeter een verkeerd uitgesproken woord niet, maar herhaal het woord gewoon op de juiste manier. Kan je kind nog geen zinnetjes van 2-3 woorden maken, begrijpt het eenvoudige opdrachten niet of kunnen zelfs gezinsleden je kind moeilijk verstaan? Overleg dan met de kinderarts.', info_sv = 'Ditt barns språkförmåga utvecklas snabbt under den här perioden. De flesta barn som fyllt 3 år bildar meningar med 3-4 ord, kan säga sitt namn och sin ålder och använder pronomen som ”jag”, ”du” och ”vi” på rätt sätt. Ordförrådet består nu av flera hundra ord och barnet lär sig nya ord varje dag. Familjemedlemmarna bör förstå det mesta av vad barnet säger, och även personer som inte känner barnet bör oftast kunna förstå hen. Vissa ljud, till exempel ”r” och ”sj”, kanske barnet ännu inte uttalar korrekt, och det är normalt i den här åldern. Stöd språkutvecklingen genom att prata mycket med barnet under dagen, svara tålmodigt på frågorna och läsa böcker tillsammans och prata om bilderna. I stället för att rätta ett ord som barnet uttalar fel kan du upprepa ordet i rätt form. Om ditt barn inte kan bilda meningar med 2-3 ord, inte förstår enkla uppmaningar eller om till och med familjemedlemmarna har svårt att förstå vad barnet säger, rådgör med barnläkaren.' WHERE day_number = 1096 AND is_active AND md5(coalesce(info,'')) = '018ddfe00e86e5beb604a38e0c55104d' AND md5(coalesce(info_en,'')) = '5d8c56d3e010fb5f611a5fd4a1b99dd1' AND md5(coalesce(info_ru,'')) = 'a5d0fb0fd3777deabff4fb21b22f9b3f' AND md5(coalesce(info_tr,'')) = '53b8f99f82cbd4da41baf783be8f4533' AND md5(coalesce(info_kk,'')) = '948e151ee51a85bb9715f9bae0f91a45' AND md5(coalesce(info_de,'')) = 'da007e513893c8ada6f88e8a8de4eb99' AND md5(coalesce(info_ar,'')) = '59f71001bc2dec545020d5ec9ff8db38' AND md5(coalesce(info_uz,'')) = '8a73b3124af4bab040006ac1bc0ba5f8' AND md5(coalesce(info_ka,'')) = 'e85121c5ae96ebc4e9543829041fcc1b' AND md5(coalesce(info_zh,'')) = '539129e205dba47320197682fe8d289c' AND md5(coalesce(info_id,'')) = '9a7fbf15781ede32aab9bfbefb7b38de' AND md5(coalesce(info_fr,'')) = 'b199a72a0dd0390d587bcb4e9ed7f708' AND md5(coalesce(info_es,'')) = 'bb7578be8807b3f198c56f85bf7499d6' AND md5(coalesce(info_pt,'')) = '31e11732c2922ffab78aac4ac3c6eaa2' AND md5(coalesce(info_vi,'')) = '6e41114d9f3f4a3c0ce842b0bd661f9b' AND md5(coalesce(info_hi,'')) = '695dd8f2bb1484f1200756a470bff3e1' AND md5(coalesce(info_ja,'')) = 'f81aaaaf4fbdc39b085abaeb811ef1e9' AND md5(coalesce(info_ko,'')) = '4edb40ff18d555afe548677170902805' AND md5(coalesce(info_pl,'')) = '7ae86b4ade25de0be885034cea167926' AND md5(coalesce(info_nl,'')) = 'dd29a153362514c9b4ae601034f2e1c8' AND md5(coalesce(info_sv,'')) = '0379009f35459225442f4152cd173219';
UPDATE public.baby_daily_info SET info = '3 yaşından etibarən övladınız yaşıdları ilə oynamağa daha çox maraq göstərir və bir çox ailə bu dövrdə uşağını bağçaya verməyi düşünür. Bağça uşağın paylaşmağı, növbə gözləməyi və qaydalara əməl etməyi öyrənməsinə, sosial bacarıqlarının inkişafına kömək edir. Lakin bağçaya alışmaq hər uşaq üçün eyni sürətlə getmir. İlk günlərdə ağlamaq, sizdən ayrılmaq istəməmək, yuxu və iştahda qısa müddətli dəyişikliklər normaldır. Uyğunlaşmanı asanlaşdırmaq üçün bağçaya bir neçə gün əvvəldən birlikdə gedin, ilk həftələrdə orada qalma müddətini tədricən artırın. Ayrılarkən gizlicə getməyin: qısa və sakit şəkildə vidalaşın, nə vaxt qayıdacağınızı onun anlayacağı şəkildə deyin (məsələn, "nahardan sonra gələcəyəm") və sözünüzə əməl edin. Evdən sevdiyi kiçik oyuncağı yanında aparması ona güvən verə bilər. Əgər uyğunlaşma bir neçə həftədən sonra da çox çətin keçirsə, səbəbi müəllimlərlə birlikdə araşdırın.', info_en = 'From age 3, your child shows more interest in playing with peers, and many families consider sending their child to preschool at this time. Preschool helps children learn to share, take turns and follow rules, and supports the development of their social skills. However, settling into preschool doesn''t happen at the same pace for every child. In the first days, crying, not wanting to separate from you, and short-term changes in sleep and appetite are normal. To make the adjustment easier, visit the preschool together for a few days beforehand, and gradually increase the time they spend there during the first weeks. Don''t sneak away when you leave: say goodbye briefly and calmly, tell them when you''ll be back in a way they can understand (for example, "I''ll come after lunch"), and keep your word. Bringing a small favorite toy from home can give them a sense of security. If settling in is still very hard after several weeks, look into the reasons together with the teachers.', info_ru = 'С 3 лет ваш ребёнок проявляет всё больший интерес к играм со сверстниками, и многие семьи в этот период задумываются о детском саде. Детский сад помогает ребёнку научиться делиться, ждать своей очереди и соблюдать правила, способствует развитию социальных навыков. Однако привыкание к детскому саду проходит у каждого ребёнка в своём темпе. В первые дни плач, нежелание расставаться с вами, кратковременные изменения сна и аппетита являются нормой. Чтобы облегчить адаптацию, начните ходить в детский сад вместе за несколько дней до начала, а в первые недели постепенно увеличивайте время пребывания там. Не уходите тайком: попрощайтесь коротко и спокойно, понятными ему словами скажите, когда вернётесь (например, «я приду после обеда»), и сдержите слово. Маленькая любимая игрушка из дома может придать ему уверенности. Если и через несколько недель адаптация проходит очень тяжело, выясните причину вместе с воспитателями.', info_tr = '3 yaşından itibaren çocuğunuz yaşıtlarıyla oynamaya daha fazla ilgi gösterir ve birçok aile bu dönemde çocuğunu kreşe göndermeyi düşünür. Kreş, çocuğun paylaşmayı, sırasını beklemeyi ve kurallara uymayı öğrenmesine, sosyal becerilerinin gelişmesine yardımcı olur. Ancak kreşe alışma her çocukta aynı hızda gerçekleşmez. İlk günlerde ağlamak, sizden ayrılmak istememek, uyku ve iştahta kısa süreli değişiklikler normaldir. Uyum sürecini kolaylaştırmak için birkaç gün önceden kreşe birlikte gidin, ilk haftalarda orada kalma süresini kademeli olarak artırın. Ayrılırken gizlice gitmeyin: kısa ve sakin bir şekilde vedalaşın, ne zaman döneceğinizi onun anlayacağı şekilde söyleyin (örneğin, "öğle yemeğinden sonra geleceğim") ve sözünüzü tutun. Evden sevdiği küçük bir oyuncağı yanında götürmesi ona güven verebilir. Uyum süreci birkaç hafta sonra da çok zor geçiyorsa, nedenini öğretmenlerle birlikte araştırın.', info_kk = '3 жастан бастап балаңыз құрдастарымен ойнауға көбірек қызығушылық танытады және көптеген отбасылар осы кезеңде баласын балабақшаға беруді ойлайды. Балабақша баланың бөлісуді, кезек күтуді және ережелерді сақтауды үйренуіне, әлеуметтік дағдыларының дамуына көмектеседі. Алайда балабақшаға бейімделу әр балада бірдей қарқынмен жүрмейді. Алғашқы күндері жылау, Сізден ажырағысы келмеу, ұйқы мен тәбеттің қысқа мерзімді өзгерістері қалыпты жағдай. Бейімделуді жеңілдету үшін балабақшаға бірнеше күн бұрын бірге барып жүріңіз, алғашқы апталарда онда болу уақытын біртіндеп ұзартыңыз. Қоштасқанда білдірмей кетіп қалмаңыз: қысқа әрі сабырлы түрде қоштасыңыз, қашан оралатыныңызды оған түсінікті етіп айтыңыз (мысалы, «түскі астан кейін келемін») және уәдеңізде тұрыңыз. Үйден өзі жақсы көретін кішкентай ойыншығын ала баруы оған сенімділік беруі мүмкін. Егер бірнеше аптадан кейін де бейімделу өте қиын өтсе, оның себебін тәрбиешілермен бірге анықтаңыз.', info_de = 'Ab 3 Jahren zeigt dein Kind immer mehr Interesse daran, mit Gleichaltrigen zu spielen, und viele Familien denken in dieser Zeit darüber nach, ihr Kind in den Kindergarten zu geben. Der Kindergarten hilft dem Kind, Teilen, Abwarten und das Einhalten von Regeln zu lernen, und fördert seine sozialen Fähigkeiten. Doch nicht jedes Kind gewöhnt sich gleich schnell an den Kindergarten. Weinen, nicht von dir getrennt sein wollen sowie vorübergehende Veränderungen bei Schlaf und Appetit sind in den ersten Tagen normal. Um die Eingewöhnung zu erleichtern, geht schon einige Tage vorher gemeinsam in den Kindergarten und verlängere in den ersten Wochen die Aufenthaltsdauer nach und nach. Schleiche dich beim Abschied nicht heimlich davon: Verabschiede dich kurz und ruhig, sag ihm so, dass es das verstehen kann, wann du zurückkommst (zum Beispiel „Ich komme nach dem Mittagessen“), und halte dein Wort. Ein kleines Lieblingsspielzeug von zu Hause kann ihm Sicherheit geben. Wenn die Eingewöhnung auch nach einigen Wochen noch sehr schwerfällt, sucht gemeinsam mit den Erzieherinnen und Erziehern nach der Ursache.', info_ar = 'ابتداءً من عمر 3 سنوات، يُبدي طفلكِ اهتمامًا أكبر باللعب مع أقرانه، وتفكر عائلات كثيرة في هذه المرحلة في إلحاق طفلها بالروضة. فالروضة تساعد الطفل على تعلّم المشاركة وانتظار دوره واتباع القواعد، وتنمّي مهاراته الاجتماعية. لكن التأقلم مع الروضة لا يحدث بالسرعة نفسها لدى جميع الأطفال. ففي الأيام الأولى يكون البكاء، وعدم الرغبة في الابتعاد عنكِ، والتغيرات المؤقتة في النوم والشهية أمورًا طبيعية. ولتسهيل التأقلم، اذهبي معه إلى الروضة قبل بدء الدوام ببضعة أيام، وزيدي مدة بقائه فيها تدريجيًا خلال الأسابيع الأولى. ولا تغادري خلسة عند الافتراق، بل ودّعيه بإيجاز وهدوء، وأخبريه متى ستعودين بطريقة يفهمها (مثلًا: «سآتي بعد الغداء»)، والتزمي بوعدكِ. وقد يمنحه اصطحاب لعبة صغيرة يحبها من المنزل شعورًا بالأمان. وإذا ظل التأقلم صعبًا جدًا حتى بعد بضعة أسابيع، فابحثي عن السبب بالتعاون مع المعلمين.', info_uz = '3 yoshdan boshlab farzandingiz tengdoshlari bilan o‘ynashga ko‘proq qiziqish bildiradi va ko‘plab oilalar bu davrda bolasini bog‘chaga berishni o‘ylaydi. Bog‘cha bolaga bo‘lishishni, navbat kutishni va qoidalarga amal qilishni o‘rganishda, ijtimoiy ko‘nikmalarini rivojlantirishda yordam beradi. Biroq bog‘chaga moslashish har bir bolada bir xil tezlikda kechmaydi. Dastlabki kunlarda yig‘lash, sizdan ajralishni istamaslik, uyqu va ishtahadagi qisqa muddatli o‘zgarishlar odatiy holdir. Moslashishni osonlashtirish uchun bog‘chaga bir necha kun oldindan birga boring, dastlabki haftalarda u yerda qolish vaqtini asta-sekin oshiring. Xayrlashayotganda yashirincha ketib qolmang: qisqa va xotirjam xayrlashing, qachon qaytishingizni u tushunadigan tarzda ayting (masalan, «tushlikdan keyin kelaman») va va’dangizning ustidan chiqing. Uydan o‘zi yaxshi ko‘radigan kichik o‘yinchoqni olib borishi unga ishonch bag‘ishlashi mumkin. Agar bir necha haftadan keyin ham moslashish juda qiyin kechsa, sababini tarbiyachilar bilan birgalikda aniqlang.', info_ka = '3 წლის ასაკიდან თქვენი ბავშვი თანატოლებთან თამაშით უფრო მეტად ინტერესდება და ბევრი ოჯახი ამ პერიოდში ბავშვის საბავშვო ბაღში შეყვანაზე ფიქრობს. საბავშვო ბაღი ეხმარება ბავშვს, ისწავლოს გაზიარება, რიგის ლოდინი და წესების დაცვა, და ხელს უწყობს მისი სოციალური უნარების განვითარებას. თუმცა ბაღთან შეგუება ყველა ბავშვთან ერთნაირი სისწრაფით არ მიმდინარეობს. პირველ დღეებში ტირილი, თქვენგან დაშორების სურვილის არქონა, ძილისა და მადის ხანმოკლე ცვლილებები ნორმალურია. შეგუების გასაადვილებლად ბაღში რამდენიმე დღით ადრე ერთად იარეთ, ხოლო პირველ კვირებში იქ დარჩენის დრო თანდათან გაზარდეთ. დამშვიდობებისას ჩუმად ნუ წახვალთ: მოკლედ და მშვიდად დაემშვიდობეთ, მისთვის გასაგებად უთხარით, როდის დაბრუნდებით (მაგალითად, „სადილის შემდეგ მოვალ“), და შეასრულეთ დანაპირები. სახლიდან წაღებული პატარა საყვარელი სათამაშო შეიძლება მას თავდაჯერებულობას მატებდეს. თუ რამდენიმე კვირის შემდეგაც შეგუება ძალიან რთულად მიმდინარეობს, მიზეზი აღმზრდელებთან ერთად გაარკვიეთ.', info_zh = '从3岁起，孩子对和同龄人一起玩耍表现出更大的兴趣，很多家庭也会在这个时候考虑送孩子上幼儿园。幼儿园能帮助孩子学会分享、轮流等待和遵守规则，促进社交能力的发展。不过，每个孩子适应幼儿园的速度并不相同。最初几天哭闹、不愿意和您分开，以及睡眠和食欲出现短暂变化，都是正常的。为了让孩子更顺利地适应，可以提前几天和孩子一起去幼儿园看看，并在最初几周逐渐延长孩子在园的时间。离开时不要偷偷溜走：简短而平静地道别，用孩子能理解的方式告诉孩子您什么时候回来（例如“吃完午饭我就来接你”），并说到做到。让孩子从家里带一个心爱的小玩具，也能给孩子带来安全感。如果几周后适应仍然非常困难，请和老师一起找找原因。', info_id = 'Mulai usia 3 tahun, anak Anda semakin tertarik bermain dengan teman sebayanya, dan banyak keluarga mulai mempertimbangkan untuk memasukkannya ke taman kanak-kanak pada masa ini. Taman kanak-kanak membantu anak belajar berbagi, menunggu giliran, dan mematuhi aturan, serta mendukung perkembangan keterampilan sosialnya. Namun, proses beradaptasi tidak berlangsung dengan kecepatan yang sama pada setiap anak. Pada hari-hari pertama, menangis, tidak mau berpisah dari Anda, serta perubahan sementara pada pola tidur dan nafsu makan adalah hal yang normal. Untuk memudahkan adaptasi, kunjungi sekolah bersama si Kecil beberapa hari sebelumnya, lalu tambah lama waktunya di sana secara bertahap pada minggu-minggu pertama. Jangan pergi diam-diam saat berpisah: ucapkan selamat tinggal dengan singkat dan tenang, beri tahu kapan Anda akan kembali dengan cara yang dapat ia pahami (misalnya, "Nanti dijemput setelah makan siang, ya"), lalu tepati janji Anda. Membawa mainan kecil kesayangannya dari rumah dapat memberinya rasa aman. Jika setelah beberapa minggu adaptasi masih sangat sulit, cari tahu penyebabnya bersama para guru.', info_fr = 'À partir de 3 ans, votre enfant s’intéresse davantage aux jeux avec les enfants de son âge, et de nombreuses familles envisagent alors de l’inscrire à l’école maternelle. La maternelle aide l’enfant à apprendre à partager, à attendre son tour et à respecter des règles, et favorise le développement de ses compétences sociales. Cependant, l’adaptation ne se fait pas au même rythme pour tous les enfants. Les premiers jours, il est normal qu’il pleure, qu’il refuse de se séparer de vous ou que son sommeil et son appétit changent pendant une courte période. Pour faciliter l’adaptation, rendez-vous ensemble à l’école quelques jours avant la rentrée, puis augmentez progressivement le temps qu’il y passe au cours des premières semaines. Ne partez pas en cachette au moment de la séparation : dites-lui au revoir brièvement et calmement, expliquez-lui quand vous reviendrez avec des mots qu’il peut comprendre (par exemple, « je viendrai te chercher après le déjeuner ») et tenez parole. Emporter de la maison un petit jouet qu’il aime peut le rassurer. Si l’adaptation reste très difficile après plusieurs semaines, cherchez-en la cause avec l’équipe enseignante.', info_es = 'A partir de los 3 años, tu peque muestra más interés por jugar con otros niños de su edad, y muchas familias se plantean en esta etapa llevarlo a la escuela infantil. La escuela infantil le ayuda a aprender a compartir, esperar su turno y seguir normas, y favorece el desarrollo de sus habilidades sociales. Sin embargo, no todos los niños se adaptan al mismo ritmo. En los primeros días es normal que llore, que no quiera separarse de ti y que su sueño y su apetito cambien durante un tiempo. Para facilitar la adaptación, visitad juntos la escuela unos días antes y, durante las primeras semanas, aumenta poco a poco el tiempo que pasa allí. Al despedirte, no te vayas a escondidas: despídete de forma breve y tranquila, dile cuándo volverás de una manera que pueda entender (por ejemplo, «vendré después de comer») y cumple tu palabra. Llevar de casa un juguete pequeño que le guste puede darle seguridad. Si después de varias semanas la adaptación sigue siendo muy difícil, busca la causa junto con los educadores.', info_pt = 'A partir dos 3 anos, a criança mostra mais interesse em brincar com outras crianças da mesma idade, e muitas famílias pensam nesta fase em inscrevê-la no jardim de infância. O jardim de infância ajuda a criança a aprender a partilhar, a esperar pela sua vez e a cumprir regras, além de favorecer o desenvolvimento das competências sociais. No entanto, a adaptação não acontece ao mesmo ritmo em todas as crianças. Nos primeiros dias, é normal que chore, que não se queira separar de si e que haja alterações passageiras no sono e no apetite. Para facilitar a adaptação, visitem juntos o jardim de infância alguns dias antes e, nas primeiras semanas, aumente gradualmente o tempo que a criança lá passa. Na hora da despedida, não saia às escondidas: despeça-se de forma breve e calma, diga-lhe quando vai voltar de uma forma que consiga compreender (por exemplo, «venho buscar-te depois do almoço») e cumpra o que disse. Levar de casa um pequeno brinquedo de que goste pode dar-lhe segurança. Se, ao fim de várias semanas, a adaptação continuar a ser muito difícil, procure perceber a causa juntamente com os educadores.', info_vi = 'Từ 3 tuổi, con ngày càng thích chơi với các bạn cùng trang lứa, và nhiều gia đình bắt đầu nghĩ đến việc cho con đi mẫu giáo vào thời điểm này. Trường mẫu giáo giúp con học cách chia sẻ, chờ đến lượt, tuân theo quy tắc và phát triển các kỹ năng xã hội. Tuy nhiên, không phải trẻ nào cũng làm quen với trường mẫu giáo nhanh như nhau. Trong những ngày đầu, việc con khóc, không muốn rời xa bạn, hay có những thay đổi ngắn hạn về giấc ngủ và ăn uống là điều bình thường. Để giúp con thích nghi dễ dàng hơn, bạn hãy cùng con đến trường vài ngày trước khi con bắt đầu đi học, và trong những tuần đầu, hãy tăng dần thời gian con ở lại trường. Khi chia tay, đừng lén bỏ đi: hãy tạm biệt con ngắn gọn và bình tĩnh, nói cho con biết khi nào bạn quay lại theo cách con hiểu được (ví dụ: “Ăn trưa xong mẹ sẽ đến đón con”) và giữ đúng lời hứa. Cho con mang theo một món đồ chơi nhỏ yêu thích từ nhà có thể giúp con cảm thấy yên tâm hơn. Nếu sau vài tuần con vẫn rất khó thích nghi, bạn hãy cùng các cô giáo tìm hiểu nguyên nhân.', info_hi = '3 साल की उम्र से आपका बच्चा हमउम्र बच्चों के साथ खेलने में ज़्यादा रुचि दिखाने लगता है, और कई परिवार इसी समय बच्चे को प्ले स्कूल या किंडरगार्टन भेजने के बारे में सोचते हैं। प्ले स्कूल बच्चे को चीज़ें बाँटना, अपनी बारी का इंतज़ार करना और नियमों का पालन करना सिखाने में मदद करता है, साथ ही उसके सामाजिक कौशल का विकास करता है। लेकिन हर बच्चा प्ले स्कूल में एक जैसी गति से नहीं ढलता। शुरुआती दिनों में रोना, आपसे अलग न होना चाहना, और नींद व भूख में थोड़े समय के लिए बदलाव आना सामान्य है। बच्चे को आसानी से ढलने में मदद के लिए शुरुआत से कुछ दिन पहले से उसके साथ प्ले स्कूल जाएँ, और पहले कुछ हफ़्तों में वहाँ रहने का समय धीरे-धीरे बढ़ाएँ। विदा लेते समय चुपके से न जाएँ: छोटे और शांत तरीके से अलविदा कहें, आप कब वापस आएँगे यह उसे समझ आने वाले तरीके से बताएँ (जैसे, “मैं दोपहर के खाने के बाद आऊँगी”) और अपनी बात निभाएँ। घर से अपना कोई छोटा पसंदीदा खिलौना साथ ले जाना उसे भरोसा दे सकता है। अगर कुछ हफ़्तों के बाद भी ढलना बहुत मुश्किल हो रहा हो, तो शिक्षकों के साथ मिलकर इसकी वजह पता करें।', info_ja = '3歳ごろから、お子さんは同年代の子と遊ぶことにより興味を示すようになり、この時期に入園を考えるご家庭も多くあります。園での生活は、分け合うこと、順番を待つこと、ルールを守ることを学び、社会性を育むのに役立ちます。ただし、園に慣れるペースは子どもによってさまざまです。最初の数日間、泣いたり、親から離れたがらなかったり、睡眠や食欲に一時的な変化が見られたりするのは普通のことです。慣れやすくするために、入園の数日前から一緒に園に行ってみて、最初の数週間は園で過ごす時間を少しずつ延ばしていきましょう。別れるときにこっそりいなくなるのはやめましょう。短く穏やかにお別れを言い、いつ迎えに来るのかをお子さんにわかる言葉で伝え（たとえば「お昼ごはんのあとに来るね」）、その約束を守ってください。家からお気に入りの小さなおもちゃを持っていくと、安心できることがあります。数週間たっても慣れるのがとても難しい場合は、先生と一緒に原因を探ってみましょう。', info_ko = '3세부터 아이는 또래와 노는 데 더 많은 관심을 보이고, 많은 가정이 이 시기에 아이를 유치원에 보낼지 고민해요. 유치원은 아이가 나누기, 차례 기다리기, 규칙 지키기를 배우고 사회성을 키우는 데 도움이 돼요. 하지만 유치원에 적응하는 속도는 아이마다 달라요. 처음 며칠 동안 울거나, 부모와 떨어지기 싫어하거나, 잠과 식욕에 일시적인 변화가 생기는 것은 정상이에요. 적응을 돕기 위해 며칠 전부터 함께 유치원에 가 보고, 처음 몇 주 동안은 머무는 시간을 조금씩 늘려 주세요. 헤어질 때 몰래 사라지지 마세요. 짧고 차분하게 인사하고, 언제 돌아올지 아이가 이해할 수 있는 방식으로 말해 주고(예: ''점심 먹고 나서 올게''), 그 약속을 꼭 지켜 주세요. 집에서 좋아하는 작은 장난감을 가져가게 하면 안정감을 줄 수 있어요. 몇 주가 지나도 적응이 매우 힘들다면 선생님과 함께 그 원인을 살펴보세요.', info_pl = 'Od 3. roku życia Twoje dziecko coraz chętniej bawi się z rówieśnikami, a wiele rodzin zaczyna w tym okresie myśleć o posłaniu go do przedszkola. Przedszkole pomaga dziecku nauczyć się dzielenia, czekania na swoją kolej i przestrzegania zasad oraz wspiera rozwój umiejętności społecznych. Jednak nie każde dziecko przyzwyczaja się do przedszkola w tym samym tempie. W pierwszych dniach płacz, niechęć do rozstania z Tobą oraz krótkotrwałe zmiany w śnie i apetycie są normalne. Aby ułatwić adaptację, odwiedźcie razem przedszkole kilka dni wcześniej, a w pierwszych tygodniach stopniowo wydłużaj czas, jaki dziecko tam spędza. Przy rozstaniu nie wymykaj się ukradkiem: pożegnaj się krótko i spokojnie, powiedz, kiedy wrócisz, w sposób zrozumiały dla dziecka (na przykład „przyjdę po obiedzie”), i dotrzymaj słowa. Mała ulubiona zabawka zabrana z domu może dodać mu poczucia bezpieczeństwa. Jeśli adaptacja nadal przebiega bardzo trudno po kilku tygodniach, poszukajcie przyczyny razem z nauczycielami.', info_nl = 'Vanaf 3 jaar toont je kind steeds meer interesse in spelen met leeftijdsgenootjes, en veel ouders denken in deze periode na over een peuterspeelzaal, kinderopvang of kleuterklas. Daar leert je kind delen, op zijn beurt wachten en zich aan regels houden, en ontwikkelt het sociale vaardigheden. Toch went niet elk kind even snel. Huilen, niet bij je weg willen en kortdurende veranderingen in slaap en eetlust zijn de eerste dagen normaal. Ga een paar dagen van tevoren samen kijken om het wennen makkelijker te maken, en bouw in de eerste weken de tijd dat je kind er blijft geleidelijk op. Sluip bij het afscheid niet stiekem weg: neem kort en rustig afscheid, vertel op een manier die je kind begrijpt wanneer je terugkomt (bijvoorbeeld ‘ik kom na het middageten’) en houd je aan je woord. Een klein lievelingsknuffeltje of speeltje van thuis kan je kind een gevoel van veiligheid geven. Verloopt het wennen na een paar weken nog steeds erg moeizaam? Zoek dan samen met de leidsters of leerkrachten naar de oorzaak.', info_sv = 'Från 3 års ålder visar ditt barn allt större intresse för att leka med jämnåriga, och många familjer funderar på förskola under den här perioden. Förskolan hjälper barnet att lära sig dela med sig, vänta på sin tur och följa regler, och bidrar till att utveckla de sociala förmågorna. Men inskolningen går inte lika fort för alla barn. Under de första dagarna är det normalt att barnet gråter, inte vill skiljas från dig och att sömn och aptit tillfälligt förändras. För att underlätta inskolningen kan ni besöka förskolan tillsammans några dagar i förväg och sedan gradvis förlänga tiden barnet stannar där under de första veckorna. Smit inte iväg när ni skiljs åt: säg hej då kort och lugnt, berätta när du kommer tillbaka på ett sätt som barnet förstår (till exempel ”jag kommer efter lunch”) och håll det du lovar. Att ta med en liten favoritleksak hemifrån kan ge barnet trygghet. Om inskolningen fortfarande är mycket svår efter några veckor, försök att tillsammans med pedagogerna ta reda på orsaken.' WHERE day_number = 1097 AND is_active AND md5(coalesce(info,'')) = 'e7e1423f280ff2793d00dc3eadfa8a00' AND md5(coalesce(info_en,'')) = '126617581057a538208997ba6fbf628f' AND md5(coalesce(info_ru,'')) = 'f1fa9471fa2639cd82c4df2fb156bfb4' AND md5(coalesce(info_tr,'')) = 'c232db3bd7dfdbf2f645e07bda0be3db' AND md5(coalesce(info_kk,'')) = '38655ea38d64c858b5de94d3f4040c4b' AND md5(coalesce(info_de,'')) = '79344b00440cb8355bfddcda05f4e502' AND md5(coalesce(info_ar,'')) = '1cf772382f892edd92be71247895e526' AND md5(coalesce(info_uz,'')) = '4e8bf3923033960b2de1cb9422d54ebc' AND md5(coalesce(info_ka,'')) = 'b9ef208b90e1b9773e42bdb0658993f6' AND md5(coalesce(info_zh,'')) = 'dcb38f9bbbbc14bd8770749513b5589a' AND md5(coalesce(info_id,'')) = '8772e78c1ec93760fc619124754abe72' AND md5(coalesce(info_fr,'')) = '3884a11c2e4e4abcbe8a1e0285cede69' AND md5(coalesce(info_es,'')) = '2aeb0e820e9719dae50b815d0888c7df' AND md5(coalesce(info_pt,'')) = 'b270e4e188b774c824e971df788e5992' AND md5(coalesce(info_vi,'')) = 'c8437e12f6035a26851b6f541985bdc8' AND md5(coalesce(info_hi,'')) = '10e19f27a3877b031eaa3b1a605f6ac6' AND md5(coalesce(info_ja,'')) = '8eafbccfd80fe1ce016595ebf95494f2' AND md5(coalesce(info_ko,'')) = 'f1ae7fcb61b71dae921a1fa06c5b9251' AND md5(coalesce(info_pl,'')) = '8e907c4c2b99bff8cdb11c73c8ccb1b5' AND md5(coalesce(info_nl,'')) = '2355d7117ee6107cb8c172fadc01b707' AND md5(coalesce(info_sv,'')) = '5308a4f02d18976eaffb0a94ae2f79f4';
UPDATE public.baby_daily_info SET info = '2 yaş sindromu nə qədər tanınsa da, bir çox valideyn 3 yaş dövrünün də heç də asan keçmədiyini görür. Bu yaşda uşaq müstəqil olmaq istəyir, "özüm edəcəyəm" deyir, qaydaları sınayır və istədiyi olmayanda hirslənə bilər. Duyğularını sözlə ifadə etmək bacarığı hələ tam inkişaf etmədiyi üçün qəzəb tutmaları, ağlama və inad davranışları görülə bilər. Bu, onun inkişafının normal bir hissəsidir. Belə anlarda sakit qalmağa çalışın və onun hissini adlandırın: "Oyuncağı vermədiyim üçün hirsləndin, başa düşürəm". Mümkün olduqda seçim imkanı verin: "Mavi köynəyi geyinək, yoxsa qırmızını?" Qaydaları az, aydın və hər dəfə eyni şəkildə tətbiq edin. Fiziki cəza və qışqırıq davranışı düzəltmir, əksinə gərginliyi artırır. Yaxşı davranışlarını isə dərhal fərq edib tərifləyin. Qəzəb tutmaları çox tez-tez olursa, uzun sürürsə və ya uşaq özünə və başqalarına zərər verirsə, uşaq həkimi ilə danışın.', info_en = 'As well known as the "terrible twos" are, many parents find that age 3 isn''t easy either. At this age, a child wants to be independent, says "I''ll do it myself", tests the rules, and may get angry when they don''t get their way. Because their ability to express feelings in words isn''t fully developed yet, tantrums, crying and stubborn behavior may appear. This is a normal part of their development. In these moments, try to stay calm and name their feeling: "You''re angry because I didn''t give you the toy, I understand." Offer choices when possible: "Shall we wear the blue shirt or the red one?" Keep rules few and clear, and apply them the same way every time. Physical punishment and shouting don''t correct behavior; on the contrary, they increase tension. Notice good behavior right away and praise it. If tantrums happen very often, last a long time, or if your child hurts themselves or others, talk to a pediatrician.', info_ru = 'Хотя о кризисе 2 лет знают многие, немало родителей замечают, что и период 3 лет проходит совсем не просто. В этом возрасте ребёнок стремится к самостоятельности, говорит «я сам», проверяет правила на прочность и может злиться, когда не получает желаемого. Поскольку умение выражать чувства словами ещё не до конца сформировалось, возможны вспышки гнева, плач и упрямство. Это нормальная часть его развития. В такие моменты старайтесь сохранять спокойствие и называйте его чувство: «Ты сердишься, потому что я не даю тебе игрушку, я понимаю». Когда это возможно, предлагайте выбор: «Наденем синюю футболку или красную?» Правил должно быть немного, они должны быть понятными и применяться каждый раз одинаково. Физические наказания и крик не исправляют поведение, а, наоборот, усиливают напряжение. А вот хорошее поведение сразу замечайте и хвалите. Если вспышки гнева случаются очень часто, длятся долго или ребёнок причиняет вред себе или другим, поговорите с педиатром.', info_tr = '2 yaş sendromu ne kadar bilinse de birçok ebeveyn 3 yaş döneminin de hiç kolay geçmediğini görür. Bu yaşta çocuk bağımsız olmak ister, "kendim yapacağım" der, kuralları sınar ve istediği olmadığında sinirlenebilir. Duygularını sözcüklerle ifade etme becerisi henüz tam gelişmediği için öfke nöbetleri, ağlama ve inatlaşma davranışları görülebilir. Bu, gelişiminin normal bir parçasıdır. Böyle anlarda sakin kalmaya çalışın ve duygusunu adlandırın: "Oyuncağı vermediğim için sinirlendin, anlıyorum." Mümkün olduğunda seçim hakkı tanıyın: "Mavi tişörtü mü giyelim, kırmızıyı mı?" Kuralları az, net ve her seferinde aynı şekilde uygulayın. Fiziksel ceza ve bağırmak davranışı düzeltmez, aksine gerginliği artırır. İyi davranışlarını ise hemen fark edip övün. Öfke nöbetleri çok sık oluyorsa, uzun sürüyorsa veya çocuk kendine ya da başkalarına zarar veriyorsa çocuk doktorunuzla konuşun.', info_kk = '2 жас дағдарысы көпшілікке белгілі болғанымен, көптеген ата-ана 3 жас кезеңінің де оңай өтпейтінін байқайды. Бұл жаста бала дербес болғысы келеді, «өзім істеймін» дейді, ережелерді сынайды және қалағаны болмаған кезде ашулануы мүмкін. Сезімдерін сөзбен жеткізу қабілеті әлі толық дамымағандықтан, ашу ұстамалары, жылау және қырсығу байқалуы мүмкін. Бұл оның дамуының қалыпты бөлігі. Мұндай сәттерде сабыр сақтауға тырысыңыз және оның сезімін атап айтыңыз: «Ойыншықты бермегенім үшін ашуландың, түсінемін». Мүмкіндігінше таңдау беріңіз: «Көк жейдені киеміз бе, әлде қызылын ба?» Ережелер аз әрі түсінікті болсын және оларды әр жолы бірдей қолданыңыз. Дене жазасы мен айқай мінез-құлықты түзетпейді, керісінше шиеленісті күшейтеді. Ал оның жақсы әрекеттерін бірден байқап, мақтап отырыңыз. Егер ашу ұстамалары өте жиі қайталанса, ұзаққа созылса немесе бала өзіне не басқаларға зиян келтірсе, балалар дәрігерімен сөйлесіңіз.', info_de = 'So bekannt die Trotzphase mit 2 Jahren auch ist, viele Eltern merken, dass auch das Alter von 3 Jahren alles andere als einfach ist. In diesem Alter möchte dein Kind selbstständig sein, sagt „Ich mach das selbst!“, testet Regeln aus und kann wütend werden, wenn es nicht bekommt, was es will. Da es seine Gefühle noch nicht gut in Worte fassen kann, kommt es zu Wutanfällen, Weinen und trotzigem Verhalten. Das ist ein normaler Teil seiner Entwicklung. Versuche in solchen Momenten ruhig zu bleiben und benenne sein Gefühl: „Du bist wütend, weil ich dir das Spielzeug nicht gegeben habe. Das verstehe ich.“ Biete ihm, wenn möglich, eine Wahl an: „Ziehen wir das blaue Shirt an oder das rote?“ Halte die Regeln knapp und klar und wende sie jedes Mal gleich an. Körperliche Strafen und Anschreien ändern das Verhalten nicht, sondern verstärken die Anspannung. Gutes Verhalten solltest du dagegen sofort bemerken und loben. Wenn die Wutanfälle sehr häufig auftreten, lange andauern oder dein Kind sich selbst oder andere verletzt, sprich mit deiner Kinderärztin oder deinem Kinderarzt.', info_ar = 'مهما كانت أزمة عمر 2 سنة معروفة، فإن كثيرًا من الآباء والأمهات يلاحظون أن مرحلة عمر 3 سنوات ليست سهلة أيضًا. ففي هذا العمر يرغب الطفل في الاستقلال، ويقول «سأفعلها بنفسي»، ويختبر القواعد، وقد يغضب عندما لا يحصل على ما يريد. ولأن قدرته على التعبير عن مشاعره بالكلمات لم تكتمل بعد، قد تظهر لديه نوبات غضب وبكاء وسلوكيات عناد. وهذا جزء طبيعي من نموه. حاولي في مثل هذه اللحظات أن تبقي هادئة، وسمّي له شعوره: «أنت غاضب لأنني لم أعطك اللعبة، أنا أفهمك». وامنحيه حرية الاختيار متى أمكن: «هل نلبس القميص الأزرق أم الأحمر؟» واجعلي القواعد قليلة وواضحة، وطبّقيها بالطريقة نفسها في كل مرة. فالعقاب الجسدي والصراخ لا يصلحان السلوك، بل يزيدان التوتر. وفي المقابل، لاحظي سلوكه الجيد فورًا وامدحيه. وإذا كانت نوبات الغضب متكررة جدًا، أو تستمر طويلًا، أو كان الطفل يؤذي نفسه أو الآخرين، فتحدّثي مع طبيب الأطفال.', info_uz = '2 yosh inqirozi qanchalik mashhur bo‘lmasin, ko‘plab ota-onalar 3 yosh davri ham unchalik oson kechmasligini ko‘radi. Bu yoshda bola mustaqil bo‘lishni xohlaydi, «o‘zim qilaman» deydi, qoidalarni sinab ko‘radi va xohlagani bo‘lmaganda jahli chiqishi mumkin. Hissiyotlarini so‘z bilan ifodalash ko‘nikmasi hali to‘liq rivojlanmagani uchun jahl xurujlari, yig‘lash va o‘jarlik holatlari kuzatilishi mumkin. Bu uning rivojlanishining odatiy qismidir. Bunday paytlarda xotirjam bo‘lishga harakat qiling va uning his-tuyg‘usini nomlang: «O‘yinchoqni bermaganim uchun jahling chiqdi, tushunaman». Imkon bo‘lganda tanlash imkoniyatini bering: «Ko‘k ko‘ylakni kiyamizmi yoki qizilinimi?» Qoidalar kam va aniq bo‘lsin, ularni har safar bir xil tarzda qo‘llang. Jismoniy jazo va baqirish xulq-atvorni tuzatmaydi, aksincha, zo‘riqishni kuchaytiradi. Yaxshi xatti-harakatlarini esa darhol payqab, maqtang. Agar jahl xurujlari juda tez-tez takrorlansa, uzoq davom etsa yoki bola o‘ziga yoxud boshqalarga zarar yetkazsa, pediatr bilan gaplashing.', info_ka = 'რაც არ უნდა ცნობილი იყოს 2 წლის კრიზისი, ბევრი მშობელი ამჩნევს, რომ 3 წლის ასაკიც სულაც არ არის მარტივი. ამ ასაკში ბავშვს დამოუკიდებლობა სურს, ამბობს „მე თვითონ გავაკეთებ“, წესებს ამოწმებს და შეიძლება გაბრაზდეს, როცა მისი ნება არ სრულდება. რადგან ემოციების სიტყვებით გამოხატვის უნარი ჯერ ბოლომდე არ აქვს განვითარებული, შეიძლება გამოვლინდეს ბრაზის შეტევები, ტირილი და ჯიუტობა. ეს მისი განვითარების ნორმალური ნაწილია. ასეთ დროს შეეცადეთ, მშვიდად იყოთ და დაასახელეთ მისი გრძნობა: „გაბრაზდი, რადგან სათამაშო არ მოგეცი, მესმის“. შესაძლებლობის შემთხვევაში არჩევანი მიეცით: „ლურჯი მაისური ჩავიცვათ თუ წითელი?“ წესები იყოს ცოტა და მკაფიო, და ყოველ ჯერზე ერთნაირად გამოიყენეთ. ფიზიკური დასჯა და ყვირილი ქცევას ვერ ასწორებს, პირიქით, დაძაბულობას ზრდის. სამაგიეროდ, მის კარგ საქციელს მაშინვე შეამჩნიეთ და შეაქეთ. თუ ბრაზის შეტევები ძალიან ხშირია, დიდხანს გრძელდება ან ბავშვი საკუთარ თავს ან სხვებს ზიანს აყენებს, ესაუბრეთ პედიატრს.', info_zh = '虽然“可怕的两岁”广为人知，但很多父母发现，3岁这个阶段也并不轻松。这个年龄的孩子想要独立，会说“我自己来”，会试探规则，事情不如意时可能会发脾气。由于用语言表达情绪的能力还没有完全发展，孩子可能会出现发脾气、哭闹和执拗的行为。这是孩子成长过程中正常的一部分。在这种时候，请尽量保持冷静，并说出孩子的感受：“我没给你玩具，所以你生气了，我理解。”在可能的情况下给孩子选择的机会：“我们穿蓝色的上衣，还是红色的？”规则要少而清晰，并且每次都以同样的方式执行。体罚和吼叫并不能纠正行为，反而会加剧紧张情绪。孩子表现好时，要及时注意到并给予表扬。如果孩子发脾气非常频繁、持续时间很长，或者会伤害自己或他人，请咨询儿科医生。', info_id = 'Meskipun fase "terrible two" sudah banyak dikenal, banyak orang tua mendapati bahwa usia 3 tahun pun tidak selalu mudah dilalui. Pada usia ini, anak ingin mandiri, sering berkata "aku sendiri!", menguji aturan, dan bisa marah ketika keinginannya tidak terpenuhi. Karena kemampuannya mengungkapkan perasaan dengan kata-kata belum sepenuhnya berkembang, tantrum, tangisan, dan perilaku keras kepala dapat muncul. Hal ini merupakan bagian normal dari perkembangannya. Pada saat seperti ini, cobalah tetap tenang dan sebutkan perasaannya: "Kamu marah karena mainannya tidak diberikan, ya. Aku mengerti." Jika memungkinkan, beri ia pilihan: "Mau pakai kemeja biru atau yang merah?" Buat sedikit aturan yang jelas, dan terapkan dengan cara yang sama setiap kali. Hukuman fisik dan bentakan tidak memperbaiki perilaku, justru menambah ketegangan. Sebaliknya, segera perhatikan dan puji perilaku baiknya. Jika tantrum sangat sering terjadi, berlangsung lama, atau anak menyakiti dirinya sendiri maupun orang lain, bicarakan dengan dokter anak.', info_fr = 'Si le « terrible two » est bien connu, de nombreux parents constatent que la période des 3 ans n’est pas toujours facile non plus. À cet âge, l’enfant veut être indépendant, dit « je fais tout seul », teste les règles et peut se mettre en colère quand il n’obtient pas ce qu’il veut. Comme sa capacité à exprimer ses émotions par des mots n’est pas encore pleinement développée, des crises de colère, des pleurs et des comportements d’opposition peuvent apparaître. Cela fait partie de son développement normal. Dans ces moments-là, essayez de rester calme et mettez des mots sur ce qu’il ressent : « Tu es en colère parce que je ne t’ai pas donné le jouet, je comprends. » Lorsque c’est possible, proposez-lui un choix : « On met la chemise bleue ou la rouge ? » Fixez peu de règles, des règles claires, et appliquez-les toujours de la même façon. Les punitions physiques et les cris ne corrigent pas le comportement ; au contraire, ils augmentent la tension. Remarquez en revanche ses bons comportements et félicitez-le tout de suite. Si les crises de colère sont très fréquentes, durent longtemps ou si l’enfant se fait du mal ou en fait aux autres, parlez-en à votre pédiatre.', info_es = 'Aunque los famosos «terribles dos» son muy conocidos, muchas familias descubren que la etapa de los 3 años tampoco es nada fácil. A esta edad, tu peque quiere ser independiente, dice «lo hago yo», pone a prueba las normas y puede enfadarse cuando no consigue lo que quiere. Como su capacidad para expresar sus emociones con palabras aún no está del todo desarrollada, pueden aparecer rabietas, llanto y conductas de oposición. Esto forma parte normal de su desarrollo. En esos momentos, intenta mantener la calma y pon nombre a lo que siente: «Te has enfadado porque no te he dado el juguete, lo entiendo». Cuando sea posible, ofrécele opciones: «¿Nos ponemos la camisa azul o la roja?». Establece pocas normas, que sean claras, y aplícalas siempre de la misma manera. El castigo físico y los gritos no corrigen la conducta; al contrario, aumentan la tensión. En cambio, fíjate en su buen comportamiento y elógialo enseguida. Si las rabietas son muy frecuentes, duran mucho o tu peque se hace daño a sí mismo o a los demás, habla con el pediatra.', info_pt = 'Embora os famosos «terríveis dois» sejam bem conhecidos, muitos pais percebem que a fase dos 3 anos também não é nada fácil. Nesta idade, a criança quer ser independente, diz «sou eu que faço», testa as regras e pode zangar-se quando não consegue o que quer. Como a capacidade de exprimir as emoções por palavras ainda não está totalmente desenvolvida, podem surgir birras, choro e comportamentos de teimosia. Isto faz parte do desenvolvimento normal. Nestes momentos, tente manter a calma e dê nome ao que a criança sente: «Ficaste zangado porque não te dei o brinquedo, eu percebo». Sempre que possível, dê-lhe a oportunidade de escolher: «Vestimos a camisa azul ou a vermelha?» Tenha poucas regras, claras, e aplique-as sempre da mesma forma. Os castigos físicos e os gritos não corrigem o comportamento; pelo contrário, aumentam a tensão. Já os bons comportamentos, repare neles e elogie-os de imediato. Se as birras forem muito frequentes, durarem muito tempo ou se a criança se magoar a si própria ou aos outros, fale com o pediatra.', info_vi = 'Dù “khủng hoảng tuổi lên 2” được nhiều người biết đến, không ít cha mẹ nhận thấy giai đoạn 3 tuổi cũng chẳng hề dễ dàng. Ở tuổi này, con muốn tự lập, hay nói “con tự làm”, thử thách các quy tắc và có thể nổi giận khi không được như ý. Vì khả năng diễn đạt cảm xúc bằng lời của con chưa phát triển hoàn thiện, con có thể có những cơn ăn vạ, khóc lóc và hành vi bướng bỉnh. Đây là một phần bình thường trong quá trình phát triển của con. Trong những lúc như vậy, bạn hãy cố gắng giữ bình tĩnh và gọi tên cảm xúc của con: “Con giận vì mẹ không đưa đồ chơi cho con, mẹ hiểu mà”. Khi có thể, hãy cho con lựa chọn: “Con muốn mặc áo xanh hay áo đỏ?” Hãy đặt ít quy tắc, rõ ràng và áp dụng nhất quán mỗi lần. Đánh đòn và quát mắng không giúp sửa hành vi mà ngược lại còn làm căng thẳng tăng thêm. Thay vào đó, hãy để ý và khen ngợi ngay những hành vi tốt của con. Nếu những cơn ăn vạ xảy ra quá thường xuyên, kéo dài lâu hoặc con làm tổn thương bản thân hay người khác, bạn hãy trao đổi với bác sĩ nhi khoa.', info_hi = '“टेरिबल टूज़” के बारे में भले ही बहुत लोग जानते हों, कई माता-पिता पाते हैं कि 3 साल की उम्र का दौर भी बिल्कुल आसान नहीं होता। इस उम्र में बच्चा आत्मनिर्भर बनना चाहता है, “मैं खुद करूँगा” कहता है, नियमों को परखता है, और जब उसकी मर्ज़ी पूरी न हो तो गुस्सा हो सकता है। चूँकि अपनी भावनाओं को शब्दों में व्यक्त करने की उसकी क्षमता अभी पूरी तरह विकसित नहीं हुई है, इसलिए गुस्से के दौरे, रोना और ज़िद्दी व्यवहार दिख सकते हैं। यह उसके विकास का एक सामान्य हिस्सा है। ऐसे पलों में शांत रहने की कोशिश करें और उसकी भावना को नाम दें: “मैंने खिलौना नहीं दिया इसलिए तुम्हें गुस्सा आया, मैं समझती हूँ।” जब संभव हो, उसे चुनने का मौका दें: “नीली कमीज़ पहनें या लाल वाली?” नियम कम रखें, साफ़ रखें और हर बार एक ही तरह से लागू करें। शारीरिक सज़ा और चिल्लाने से व्यवहार नहीं सुधरता, बल्कि तनाव और बढ़ता है। इसके बजाय उसके अच्छे व्यवहार पर तुरंत ध्यान दें और उसकी तारीफ़ करें। अगर गुस्से के दौरे बहुत बार आते हैं, देर तक चलते हैं, या बच्चा खुद को या दूसरों को चोट पहुँचाता है, तो शिशु रोग विशेषज्ञ से बात करें।', info_ja = '「魔の2歳児」はよく知られていますが、3歳の時期も決して楽ではないと感じる親は少なくありません。この年齢の子どもは自立したい気持ちが強く、「自分でやる」と言い、ルールを試し、思い通りにならないと怒ることがあります。気持ちを言葉で表す力がまだ十分に育っていないため、かんしゃくを起こしたり、泣いたり、意地を張ったりすることがあります。これは成長の自然な一部です。そんなときは落ち着くよう心がけ、お子さんの気持ちを言葉にしてあげましょう。「おもちゃをあげなかったから怒っているんだね、わかるよ」。できるときは選択肢を与えましょう。「青いシャツにする？それとも赤いの？」ルールは少なく、わかりやすくし、毎回同じように守らせましょう。体罰や怒鳴ることは行動を改善せず、かえって緊張を高めます。良い行動にはすぐに気づいて、ほめてあげてください。かんしゃくがとても頻繁に起こる、長く続く、またはお子さんが自分や他人を傷つける場合は、小児科医に相談しましょう。', info_ko = '''미운 두 살''은 잘 알려져 있지만, 많은 부모가 3세 시기도 결코 쉽지 않다는 것을 느껴요. 이 나이의 아이는 독립하고 싶어 하고, ''내가 할 거야''라고 말하며, 규칙을 시험해 보고, 원하는 대로 되지 않으면 화를 낼 수 있어요. 감정을 말로 표현하는 능력이 아직 충분히 발달하지 않았기 때문에 떼쓰기, 울음, 고집 부리기 같은 행동이 나타날 수 있어요. 이는 성장 과정의 자연스러운 일부예요. 이럴 때는 침착함을 유지하려고 노력하고 아이의 감정을 말로 표현해 주세요. ''장난감을 안 줘서 화가 났구나, 이해해.'' 가능할 때는 선택권을 주세요. ''파란 셔츠 입을까, 빨간 셔츠 입을까?'' 규칙은 적고 분명하게 정하고, 매번 같은 방식으로 적용하세요. 체벌과 고함은 행동을 바로잡지 못하고 오히려 긴장을 높여요. 아이가 바르게 행동하면 바로 알아차리고 칭찬해 주세요. 떼쓰기가 너무 자주 일어나거나, 오래 지속되거나, 아이가 자신이나 다른 사람을 다치게 한다면 소아청소년과 의사와 상담하세요.', info_pl = 'Choć bunt dwulatka jest powszechnie znany, wielu rodziców przekonuje się, że okres trzeciego roku życia również wcale nie jest łatwy. W tym wieku dziecko chce być samodzielne, mówi „sam zrobię”, sprawdza granice i może się złościć, gdy coś nie idzie po jego myśli. Ponieważ umiejętność wyrażania emocji słowami nie jest jeszcze w pełni rozwinięta, mogą pojawiać się napady złości, płacz i upór. To normalna część jego rozwoju. W takich chwilach staraj się zachować spokój i nazwij jego uczucia: „Złościsz się, bo nie dałam ci zabawki, rozumiem”. Gdy to możliwe, dawaj mu wybór: „Założymy niebieską koszulkę czy czerwoną?” Ustal niewiele zasad, niech będą jasne i stosuj je za każdym razem w ten sam sposób. Kary fizyczne i krzyk nie poprawiają zachowania, a wręcz przeciwnie, zwiększają napięcie. Za to od razu zauważaj i chwal dobre zachowanie dziecka. Jeśli napady złości są bardzo częste, długo trwają lub dziecko robi krzywdę sobie albo innym, porozmawiaj z pediatrą.', info_nl = 'Hoewel de ‘peuterpuberteit’ rond 2 jaar bij veel mensen bekend is, merken veel ouders dat ook de periode rond 3 jaar helemaal niet makkelijk is. Op deze leeftijd wil je kind zelfstandig zijn, zegt het ‘zelf doen’, test het regels uit en kan het boos worden als het zijn zin niet krijgt. Omdat je kind gevoelens nog niet goed onder woorden kan brengen, kun je driftbuien, huilen en koppig gedrag zien. Dit hoort gewoon bij de ontwikkeling. Probeer op zulke momenten rustig te blijven en benoem het gevoel van je kind: ‘Je bent boos omdat ik je het speelgoed niet gaf, dat snap ik.’ Geef waar mogelijk een keuze: ‘Doen we het blauwe shirt aan of het rode?’ Houd regels beperkt en duidelijk en pas ze elke keer op dezelfde manier toe. Lichamelijk straffen en schreeuwen verbeteren het gedrag niet, maar verhogen juist de spanning. Merk goed gedrag daarentegen meteen op en geef een compliment. Komen driftbuien heel vaak voor, duren ze lang of doet je kind zichzelf of anderen pijn? Praat dan met de kinderarts.', info_sv = 'Även om trotsåldern vid 2 år är välkänd upptäcker många föräldrar att 3-årsåldern inte heller är helt lätt. I den här åldern vill barnet vara självständigt, säger ”jag gör själv”, testar gränser och kan bli arg när hen inte får som hen vill. Eftersom förmågan att uttrycka känslor med ord ännu inte är fullt utvecklad kan utbrott, gråt och trots förekomma. Det är en normal del av utvecklingen. Försök att hålla dig lugn i sådana stunder och sätt ord på barnets känsla: ”Du blev arg för att jag inte gav dig leksaken, jag förstår.” Ge valmöjligheter när det går: ”Ska vi ta på den blå tröjan eller den röda?” Ha få och tydliga regler och tillämpa dem på samma sätt varje gång. Fysisk bestraffning och skrik rättar inte till beteendet, utan ökar tvärtom spänningen. Uppmärksamma och beröm däremot barnets goda beteende direkt. Om utbrotten är mycket täta, varar länge eller om barnet skadar sig själv eller andra, tala med barnläkaren.' WHERE day_number = 1098 AND is_active AND md5(coalesce(info,'')) = '7e476046b1a3e6f4bf45fd2077d2f9e9' AND md5(coalesce(info_en,'')) = '7e476046b1a3e6f4bf45fd2077d2f9e9' AND md5(coalesce(info_ru,'')) = '03d3741810732fb495d1e48607e3c4b2' AND md5(coalesce(info_tr,'')) = '1930c89d3416622291a790745511b605' AND md5(coalesce(info_kk,'')) = '3190a5e2e0d305e807c36d1c0c8bc8f3' AND md5(coalesce(info_de,'')) = 'd1691f701ae1c96b72fb7f57481a5af9' AND md5(coalesce(info_ar,'')) = '1cb87ef478b2fac158d8ea00e6c223fd' AND md5(coalesce(info_uz,'')) = '8ec8bf0bd2d66898fc3a83e025f73ba2' AND md5(coalesce(info_ka,'')) = '3640bfb3f77c690f4bc98e8ba2165918' AND md5(coalesce(info_zh,'')) = '5d3806d311b7475ad870f75ee5c488a5' AND md5(coalesce(info_id,'')) = '2553486ac605671b03133d5472f33d56' AND md5(coalesce(info_fr,'')) = '7ec4137eee4b27ba027354be0cbb5170' AND md5(coalesce(info_es,'')) = 'd51b68908b37990e142839f6aecb42e9' AND md5(coalesce(info_pt,'')) = 'a0eaa9c2084ba2d87182998ef67d2061' AND md5(coalesce(info_vi,'')) = '28aa5c2e2bb58418212f891db3f0a5ed' AND md5(coalesce(info_hi,'')) = 'b9ce6d1537544bc1901033524f58fa40' AND md5(coalesce(info_ja,'')) = 'cfd64fae003854fec139c598e4d4c257' AND md5(coalesce(info_ko,'')) = 'f1dfdd4cb162a434d1ad2c7cc2aa90b9' AND md5(coalesce(info_pl,'')) = '53751f938770a04ee5cdd698d14c7d56' AND md5(coalesce(info_nl,'')) = '96ee5ea236949f7af1be4176b0bf0900' AND md5(coalesce(info_sv,'')) = '92479abc9797c6292f390922eeb94cc8';
UPDATE public.baby_daily_info SET info = 'Övladınızın zəka inkişafı bu dövrdə xüsusilə maraqlı bir mərhələdədir. 3 yaşlı uşaq "niyə?" və "bu nədir?" suallarını tez-tez verir, səbəb-nəticə əlaqələrini anlamağa başlayır. Əşyaları rənginə, formasına və ölçüsünə görə qruplaşdıra, 3-4 hissəli sadə pazlları yığa, kiçik miqdarları saya bilir. İki addımlı sadə tapşırıqları yerinə yetirir, məsələn: "Ayaqqabılarını götür və qapının yanına qoy". Xəyali oyunlar da bu yaşda zənginləşir: oyuncaqlarla mətbəx, xəstəxana, mağaza oyunları qurur. Zəka inkişafını dəstəkləmək üçün onun suallarına səbirlə və sadə dillə cavab verin, birlikdə kitab oxuyun, pazl, kub və rəsm kimi oyunlara vaxt ayırın. Gündəlik işlərdə də öyrənmə imkanı yaradın: mağazada meyvələri saymaq, paltarları rənginə görə ayırmaq kimi. Ekran vaxtını məhdudlaşdırın: ÜST 3-4 yaşlı uşaqlar üçün gündə 1 saatdan çox ekran vaxtı tövsiyə etmir. Unutmayın ki, hər uşağın inkişaf tempi fərqlidir.', info_en = 'Your child''s cognitive development is at a particularly fascinating stage right now. A 3-year-old often asks "why?" and "what is this?" and is beginning to understand cause and effect. They can group objects by color, shape and size, put together simple 3-4 piece puzzles, and count small quantities. They can follow simple two-step instructions, for example: "Pick up your shoes and put them by the door." Pretend play also becomes richer at this age: they set up kitchen, hospital and shop games with their toys. To support their cognitive development, answer their questions patiently and in simple language, read books together, and make time for games such as puzzles, blocks and drawing. Create learning opportunities in everyday tasks too, such as counting fruit at the store or sorting clothes by color. Limit screen time: the WHO recommends no more than 1 hour of screen time a day for children aged 3-4. Remember that every child develops at their own pace.', info_ru = 'Интеллектуальное развитие вашего ребёнка сейчас находится на особенно интересном этапе. Ребёнок в 3 года часто задаёт вопросы «почему?» и «что это?» и начинает понимать причинно-следственные связи. Он может группировать предметы по цвету, форме и размеру, собирать простые пазлы из 3-4 частей, считать небольшое количество предметов. Он выполняет простые просьбы из двух шагов, например: «Возьми свои ботинки и поставь их у двери». В этом возрасте обогащаются и сюжетные игры: с игрушками он играет в кухню, больницу, магазин. Чтобы поддержать интеллектуальное развитие, терпеливо и простыми словами отвечайте на его вопросы, читайте вместе книги, уделяйте время пазлам, кубикам и рисованию. Создавайте возможности для обучения и в повседневных делах: например, считайте фрукты в магазине, раскладывайте одежду по цветам. Ограничивайте экранное время: ВОЗ не рекомендует детям 3-4 лет проводить перед экраном больше 1 часа в день. Помните, что каждый ребёнок развивается в своём темпе.', info_tr = 'Çocuğunuzun zihinsel gelişimi bu dönemde özellikle ilgi çekici bir aşamadadır. 3 yaşındaki çocuk sık sık "neden?" ve "bu ne?" soruları sorar, neden-sonuç ilişkilerini anlamaya başlar. Nesneleri rengine, şekline ve büyüklüğüne göre gruplandırabilir, 3-4 parçalı basit yapbozları tamamlayabilir, küçük miktarları sayabilir. İki adımlı basit yönergeleri yerine getirir, örneğin: "Ayakkabılarını al ve kapının yanına koy." Hayali oyunlar da bu yaşta zenginleşir: oyuncaklarıyla mutfak, hastane, market oyunları kurar. Zihinsel gelişimini desteklemek için sorularını sabırla ve basit bir dille yanıtlayın, birlikte kitap okuyun, yapboz, küp ve resim gibi oyunlara zaman ayırın. Günlük işlerde de öğrenme fırsatları yaratın: markette meyveleri saymak, kıyafetleri rengine göre ayırmak gibi. Ekran süresini sınırlayın: DSÖ, 3-4 yaşındaki çocuklar için günde 1 saatten fazla ekran süresi önermemektedir. Unutmayın, her çocuğun gelişim hızı farklıdır.', info_kk = 'Бұл кезеңде балаңыздың зияткерлік дамуы ерекше қызықты сатыда. 3 жастағы бала «неге?» және «бұл не?» деген сұрақтарды жиі қояды, себеп-салдар байланыстарын түсіне бастайды. Ол заттарды түсіне, пішініне және көлеміне қарай топтастыра алады, 3-4 бөліктен тұратын қарапайым пазлдарды құрастырып, аз мөлшерді санай алады. Екі қадамнан тұратын қарапайым тапсырмаларды орындайды, мысалы: «Аяқкиіміңді алып, есіктің жанына қой». Бұл жаста қиял ойындары да байи түседі: ойыншықтарымен ас үй, аурухана, дүкен ойындарын ойнайды. Зияткерлік дамуына қолдау көрсету үшін сұрақтарына сабырмен әрі қарапайым тілмен жауап беріңіз, бірге кітап оқыңыз, пазл, текше және сурет салу сияқты ойындарға уақыт бөліңіз. Күнделікті істерде де үйренуге мүмкіндік туғызыңыз: мысалы, дүкенде жемістерді санау, киімдерді түсіне қарай ажырату. Экран уақытын шектеңіз: ДДСҰ 3-4 жастағы балаларға күніне 1 сағаттан артық экран уақытын ұсынбайды. Әр баланың даму қарқыны әртүрлі екенін ұмытпаңыз.', info_de = 'Die geistige Entwicklung deines Kindes befindet sich in dieser Zeit in einer besonders spannenden Phase. Ein 3-jähriges Kind fragt oft „Warum?“ und „Was ist das?“ und beginnt, Ursache und Wirkung zu verstehen. Es kann Gegenstände nach Farbe, Form und Größe sortieren, einfache Puzzles mit 3-4 Teilen zusammensetzen und kleine Mengen zählen. Einfache Aufforderungen mit zwei Schritten setzt es um, zum Beispiel: „Nimm deine Schuhe und stell sie neben die Tür.“ Auch Fantasiespiele werden in diesem Alter vielfältiger: Mit seinen Spielsachen spielt es Küche, Krankenhaus oder Kaufladen. Um die geistige Entwicklung zu fördern, beantworte seine Fragen geduldig und in einfachen Worten, lest gemeinsam Bücher und nimm dir Zeit für Puzzles, Bauklötze und Malen. Schaffe auch im Alltag Gelegenheiten zum Lernen, etwa indem ihr im Laden Obst zählt oder Kleidung nach Farben sortiert. Begrenze die Bildschirmzeit: Die WHO empfiehlt für Kinder von 3-4 Jahren nicht mehr als 1 Stunde Bildschirmzeit pro Tag. Denk daran, dass sich jedes Kind in seinem eigenen Tempo entwickelt.', info_ar = 'يمر النمو الذهني لطفلكِ في هذه الفترة بمرحلة مثيرة للاهتمام بشكل خاص. فالطفل في عمر 3 سنوات يطرح كثيرًا أسئلة مثل «لماذا؟» و«ما هذا؟»، ويبدأ في فهم العلاقة بين السبب والنتيجة. ويستطيع تصنيف الأشياء حسب لونها وشكلها وحجمها، وتركيب أحاجٍ بسيطة من 3-4 قطع، وعدّ كميات صغيرة. كما ينفّذ تعليمات بسيطة من خطوتين، مثل: «خذ حذاءك وضعه بجانب الباب». وتصبح ألعاب التخيّل أكثر ثراءً في هذا العمر، فيلعب بألعابه دور المطبخ والمستشفى والمتجر. ولدعم نموه الذهني، أجيبي عن أسئلته بصبر وبلغة بسيطة، واقرئي معه الكتب، وخصّصي وقتًا لألعاب مثل الأحاجي والمكعبات والرسم. واصنعي فرصًا للتعلّم في الأنشطة اليومية أيضًا، مثل عدّ الفواكه في المتجر أو فرز الملابس حسب ألوانها. وقلّلي من وقت الشاشات، إذ لا توصي منظمة الصحة العالمية بأكثر من 1 ساعة يوميًا أمام الشاشات للأطفال بعمر 3-4 سنوات. وتذكّري أن لكل طفل وتيرة نمو مختلفة.', info_uz = 'Farzandingizning aqliy rivojlanishi bu davrda ayniqsa qiziqarli bosqichda bo‘ladi. 3 yoshli bola «nega?» va «bu nima?» degan savollarni tez-tez beradi, sabab-oqibat bog‘liqliklarini tushuna boshlaydi. Buyumlarni rangi, shakli va o‘lchamiga ko‘ra guruhlay oladi, 3-4 qismli oddiy pazllarni yig‘a oladi, kichik miqdorlarni sanay oladi. Ikki bosqichli oddiy topshiriqlarni bajaradi, masalan: «Oyoq kiyimingni ol va eshik yoniga qo‘y». Bu yoshda xayoliy o‘yinlar ham boyib boradi: o‘yinchoqlari bilan oshxona, shifoxona, do‘kon o‘yinlarini o‘ynaydi. Aqliy rivojlanishini qo‘llab-quvvatlash uchun savollariga sabr bilan va sodda tilda javob bering, birga kitob o‘qing, pazl, kubiklar va rasm chizish kabi o‘yinlarga vaqt ajrating. Kundalik ishlarda ham o‘rganish imkoniyatlarini yarating: do‘konda mevalarni sanash, kiyimlarni rangiga qarab ajratish kabi. Ekran vaqtini cheklang: JSST 3-4 yoshli bolalar uchun kuniga 1 soatdan ortiq ekran vaqtini tavsiya etmaydi. Unutmang, har bir bolaning rivojlanish sur’ati turlicha.', info_ka = 'თქვენი ბავშვის გონებრივი განვითარება ამ პერიოდში განსაკუთრებით საინტერესო ეტაპზეა. 3 წლის ბავშვი ხშირად სვამს კითხვებს „რატომ?“ და „ეს რა არის?“ და იწყებს მიზეზ-შედეგობრივი კავშირების გაგებას. მას შეუძლია ნივთების დაჯგუფება ფერის, ფორმისა და ზომის მიხედვით, 3-4 ნაწილიანი მარტივი ფაზლების აწყობა და მცირე რაოდენობების დათვლა. ასრულებს ორსაფეხურიან მარტივ დავალებებს, მაგალითად: „აიღე შენი ფეხსაცმელი და კართან დადე“. ამ ასაკში წარმოსახვითი თამაშებიც მდიდრდება: სათამაშოებით თამაშობს სამზარეულოს, საავადმყოფოსა და მაღაზიას. გონებრივი განვითარების ხელშესაწყობად მის კითხვებს მოთმინებით და მარტივი ენით უპასუხეთ, ერთად იკითხეთ წიგნები და დრო დაუთმეთ ისეთ თამაშებს, როგორიცაა ფაზლები, კუბები და ხატვა. ყოველდღიურ საქმეებშიც შექმენით სწავლის შესაძლებლობები: მაგალითად, მაღაზიაში ხილის დათვლა ან ტანსაცმლის ფერების მიხედვით დახარისხება. შეზღუდეთ ეკრანთან გატარებული დრო: ჯანმოს რეკომენდაციით, 3-4 წლის ბავშვების ეკრანული დრო დღეში 1 საათს არ უნდა აღემატებოდეს. გახსოვდეთ, რომ ყოველი ბავშვის განვითარების ტემპი განსხვავებულია.', info_zh = '这个阶段，您孩子的智力发展正处于一个特别有趣的时期。3岁的孩子经常问“为什么？”和“这是什么？”，并开始理解因果关系。孩子能够按颜色、形状和大小给物品分类，能拼好3-4块的简单拼图，还能数少量的东西。孩子能完成简单的两步指令，例如：“把你的鞋子拿起来，放到门边。”这个年龄的假想游戏也更加丰富：孩子会用玩具玩做饭、看病、开商店等游戏。为了促进智力发展，请耐心地用简单的语言回答孩子的问题，一起读书，并留出时间玩拼图、积木和画画等游戏。在日常生活中也可以创造学习机会，比如在商店里数水果、按颜色给衣服分类。请限制屏幕时间：世界卫生组织不建议3-4岁的儿童每天屏幕时间超过1小时。请记住，每个孩子的发展节奏都不一样。', info_id = 'Perkembangan kecerdasan anak Anda sedang berada pada tahap yang sangat menarik. Anak usia 3 tahun sering bertanya "kenapa?" dan "ini apa?", serta mulai memahami hubungan sebab-akibat. Ia dapat mengelompokkan benda berdasarkan warna, bentuk, dan ukurannya, menyusun puzzle sederhana yang terdiri dari 3-4 keping, serta menghitung jumlah kecil. Ia juga dapat melakukan perintah sederhana dua langkah, misalnya: "Ambil sepatumu dan taruh di dekat pintu." Permainan imajinatif pun semakin kaya pada usia ini: dengan mainannya, ia bermain masak-masakan, rumah sakit, atau toko-tokoan. Untuk mendukung perkembangan kecerdasannya, jawab pertanyaannya dengan sabar dan bahasa yang sederhana, bacalah buku bersama, dan sisihkan waktu untuk permainan seperti puzzle, balok, dan menggambar. Ciptakan juga kesempatan belajar dalam kegiatan sehari-hari, misalnya menghitung buah di toko atau memilah pakaian berdasarkan warnanya. Batasi waktu layar: WHO tidak menganjurkan waktu layar lebih dari 1 jam per hari untuk anak usia 3-4 tahun. Ingatlah bahwa setiap anak memiliki tempo perkembangan yang berbeda.', info_fr = 'Le développement intellectuel de votre enfant traverse une étape particulièrement passionnante. À 3 ans, l’enfant pose souvent des questions comme « pourquoi ? » et « c’est quoi ? », et commence à comprendre les liens de cause à effet. Il sait trier les objets selon leur couleur, leur forme et leur taille, assembler des puzzles simples de 3-4 pièces et compter de petites quantités. Il exécute des consignes simples en deux étapes, par exemple : « Prends tes chaussures et pose-les près de la porte. » Les jeux d’imagination s’enrichissent aussi à cet âge : avec ses jouets, il joue à la dînette, au docteur ou à la marchande. Pour soutenir son développement intellectuel, répondez à ses questions avec patience et des mots simples, lisez des livres ensemble et prenez le temps de jouer aux puzzles, aux cubes ou au dessin. Créez aussi des occasions d’apprendre dans la vie quotidienne, par exemple en comptant les fruits au magasin ou en triant les vêtements par couleur. Limitez le temps d’écran : l’OMS recommande de ne pas dépasser 1 heure d’écran par jour pour les enfants de 3-4 ans. N’oubliez pas que chaque enfant se développe à son propre rythme.', info_es = 'El desarrollo intelectual de tu peque se encuentra en una etapa especialmente interesante. A los 3 años, los niños preguntan a menudo «¿por qué?» y «¿qué es esto?» y empiezan a entender las relaciones de causa y efecto. Saben agrupar objetos por color, forma y tamaño, montar puzles sencillos de 3-4 piezas y contar cantidades pequeñas. Siguen instrucciones sencillas de dos pasos, por ejemplo: «Coge tus zapatos y ponlos junto a la puerta». A esta edad, el juego imaginativo también se enriquece: con sus juguetes juega a las cocinitas, a los médicos o a las tiendas. Para apoyar su desarrollo intelectual, responde a sus preguntas con paciencia y con palabras sencillas, leed libros juntos y dedica tiempo a juegos como puzles, bloques y dibujo. Crea también oportunidades de aprendizaje en el día a día, como contar las frutas en la tienda o separar la ropa por colores. Limita el tiempo de pantalla: la OMS no recomienda más de 1 hora de pantalla al día para niños de 3-4 años. Recuerda que cada niño tiene su propio ritmo de desarrollo.', info_pt = 'O desenvolvimento intelectual da criança está numa fase especialmente interessante. Aos 3 anos, a criança pergunta muitas vezes «porquê?» e «o que é isto?» e começa a compreender as relações de causa e efeito. Consegue agrupar objetos pela cor, forma e tamanho, montar puzzles simples de 3-4 peças e contar pequenas quantidades. Cumpre instruções simples de dois passos, por exemplo: «Pega nos teus sapatos e põe-nos ao pé da porta». As brincadeiras de faz de conta também se tornam mais ricas nesta idade: com os brinquedos, brinca às cozinhas, aos médicos e às lojas. Para apoiar o desenvolvimento intelectual, responda às suas perguntas com paciência e em linguagem simples, leiam livros juntos e reserve tempo para brincadeiras como puzzles, cubos e desenho. Crie também oportunidades de aprendizagem no dia a dia, como contar a fruta no supermercado ou separar a roupa por cores. Limite o tempo de ecrã: a OMS não recomenda mais de 1 hora de ecrã por dia para crianças de 3-4 anos. Não se esqueça de que cada criança tem o seu próprio ritmo de desenvolvimento.', info_vi = 'Giai đoạn này là một chặng đặc biệt thú vị trong sự phát triển trí tuệ của con. Trẻ 3 tuổi thường xuyên đặt câu hỏi “tại sao?” và “cái này là gì?”, đồng thời bắt đầu hiểu mối quan hệ nhân quả. Con có thể phân loại đồ vật theo màu sắc, hình dạng và kích thước, ghép những bộ xếp hình đơn giản 3-4 mảnh và đếm những số lượng nhỏ. Con có thể làm theo những yêu cầu đơn giản gồm hai bước, ví dụ: “Con cầm giày lên và để cạnh cửa nhé”. Các trò chơi tưởng tượng cũng phong phú hơn ở tuổi này: con dùng đồ chơi để chơi nấu ăn, khám bệnh, bán hàng. Để hỗ trợ sự phát triển trí tuệ của con, bạn hãy kiên nhẫn trả lời các câu hỏi của con bằng lời lẽ đơn giản, cùng con đọc sách và dành thời gian cho các trò chơi như xếp hình, khối gỗ và vẽ tranh. Bạn cũng có thể tạo cơ hội học hỏi trong các việc hằng ngày, chẳng hạn như đếm trái cây khi đi chợ hay phân loại quần áo theo màu sắc. Hãy hạn chế thời gian dùng màn hình: WHO khuyến nghị trẻ 3-4 tuổi không nên dùng màn hình quá 1 giờ mỗi ngày. Đừng quên rằng mỗi trẻ có tốc độ phát triển khác nhau.', info_hi = 'इस समय आपके बच्चे का बौद्धिक विकास एक खास तौर पर दिलचस्प पड़ाव पर है। 3 साल का बच्चा अक्सर “क्यों?” और “यह क्या है?” जैसे सवाल पूछता है और कारण और परिणाम के संबंध को समझने लगता है। वह चीज़ों को उनके रंग, आकार और साइज़ के हिसाब से समूहों में बाँट सकता है, 3-4 टुकड़ों वाली आसान पहेलियाँ जोड़ सकता है और छोटी संख्याएँ गिन सकता है। वह दो चरणों वाले सरल निर्देश पूरे करता है, जैसे: “अपने जूते उठाओ और दरवाज़े के पास रख दो।” इस उम्र में काल्पनिक खेल भी ज़्यादा समृद्ध हो जाते हैं: वह खिलौनों से रसोई, अस्पताल और दुकान जैसे खेल रचता है। उसके बौद्धिक विकास में मदद के लिए उसके सवालों के जवाब धैर्य से और सरल भाषा में दें, साथ मिलकर किताबें पढ़ें, और पहेलियों, ब्लॉक और चित्र बनाने जैसे खेलों के लिए समय निकालें। रोज़मर्रा के कामों में भी सीखने के मौके बनाएँ, जैसे दुकान पर फल गिनना या कपड़ों को रंग के हिसाब से अलग करना। स्क्रीन टाइम सीमित रखें: विश्व स्वास्थ्य संगठन (WHO) 3-4 साल के बच्चों के लिए दिन में 1 घंटे से ज़्यादा स्क्रीन टाइम की सलाह नहीं देता। याद रखें कि हर बच्चे के विकास की गति अलग होती है।', info_ja = 'この時期、お子さんの知的発達は特に興味深い段階にあります。3歳の子どもは「なぜ？」「これなあに？」とよく質問し、原因と結果の関係を理解し始めます。物を色や形、大きさで分けたり、3-4ピースの簡単なパズルを完成させたり、少ない数を数えたりできます。たとえば「靴を持ってドアのそばに置いてね」といった、2段階の簡単な指示に従うこともできます。この年齢では想像遊びも豊かになり、おもちゃを使って料理やお医者さん、お店屋さんごっこをします。知的発達を促すために、質問には根気よく、わかりやすい言葉で答え、一緒に本を読み、パズルや積み木、お絵かきなどの遊びの時間を作りましょう。日常生活の中でも、お店で果物を数えたり、服を色ごとに分けたりと、学びの機会を作ることができます。スクリーンタイムは制限しましょう。世界保健機関（WHO）は、3-4歳の子どもについて、1日1時間を超えるスクリーンタイムを推奨していません。子どもの発達のペースはそれぞれ違うことを忘れないでください。', info_ko = '이 시기 아이의 인지 발달은 특히 흥미로운 단계에 있어요. 3세 아이는 ''왜?'', ''이건 뭐야?'' 같은 질문을 자주 하고, 원인과 결과의 관계를 이해하기 시작해요. 물건을 색깔, 모양, 크기에 따라 분류하고, 3-4조각으로 된 간단한 퍼즐을 맞추고, 적은 수를 셀 수 있어요. 예를 들어 ''신발 들고 문 옆에 놓아 줘'' 같은 간단한 두 단계 지시도 따를 수 있어요. 이 나이에는 상상 놀이도 풍성해져서 장난감으로 부엌, 병원, 가게 놀이를 해요. 인지 발달을 돕기 위해 아이의 질문에 인내심을 갖고 쉬운 말로 대답해 주고, 함께 책을 읽고, 퍼즐, 블록, 그림 그리기 같은 놀이에 시간을 내 주세요. 가게에서 과일을 세거나 옷을 색깔별로 나누는 것처럼 일상생활 속에서도 배움의 기회를 만들어 보세요. 화면 시청 시간은 제한하세요. 세계보건기구(WHO)는 3-4세 아이에게 하루 1시간이 넘는 화면 시청을 권장하지 않아요. 아이마다 발달 속도가 다르다는 것을 기억하세요.', info_pl = 'Rozwój poznawczy Twojego dziecka jest teraz na wyjątkowo ciekawym etapie. Trzylatek często zadaje pytania „dlaczego?” i „co to jest?” oraz zaczyna rozumieć związki przyczynowo-skutkowe. Potrafi grupować przedmioty według koloru, kształtu i wielkości, układać proste puzzle z 3-4 elementów i liczyć niewielkie ilości. Wykonuje proste dwuetapowe polecenia, na przykład: „Weź swoje buty i postaw je przy drzwiach”. W tym wieku bogatsze stają się też zabawy w udawanie: dziecko urządza z zabawkami kuchnię, szpital czy sklep. Aby wspierać rozwój poznawczy, odpowiadaj na jego pytania cierpliwie i prostym językiem, czytajcie razem książki i znajdź czas na puzzle, klocki i rysowanie. Twórz okazje do nauki także w codziennych czynnościach, na przykład licząc owoce w sklepie albo segregując ubrania według kolorów. Ograniczaj czas przed ekranem: WHO nie zaleca dzieciom w wieku 3-4 lat więcej niż 1 godziny dziennie przed ekranem. Pamiętaj, że każde dziecko rozwija się we własnym tempie.', info_nl = 'De cognitieve ontwikkeling van je kind zit nu in een bijzonder boeiende fase. Een kind van 3 jaar vraagt vaak ‘waarom?’ en ‘wat is dat?’ en begint oorzaak en gevolg te begrijpen. Je kind kan voorwerpen sorteren op kleur, vorm en grootte, eenvoudige puzzels van 3-4 stukjes maken en kleine hoeveelheden tellen. Het voert eenvoudige opdrachten in twee stappen uit, bijvoorbeeld: ‘Pak je schoenen en zet ze bij de deur.’ Ook het fantasiespel wordt op deze leeftijd rijker: met speelgoed speelt je kind keukentje, ziekenhuis of winkeltje. Beantwoord vragen geduldig en in eenvoudige taal, lees samen boekjes en maak tijd voor puzzels, blokken en tekenen om de cognitieve ontwikkeling te ondersteunen. Creëer ook in dagelijkse bezigheden leermomenten, zoals fruit tellen in de winkel of kleding op kleur sorteren. Beperk de schermtijd: de WHO raadt voor kinderen van 3-4 jaar niet meer dan 1 uur schermtijd per dag aan. Vergeet niet dat elk kind zich in zijn eigen tempo ontwikkelt.', info_sv = 'Ditt barns kognitiva utveckling befinner sig nu i en särskilt spännande fas. Ett barn på 3 år frågar ofta ”varför?” och ”vad är det här?” och börjar förstå samband mellan orsak och verkan. Barnet kan sortera föremål efter färg, form och storlek, lägga enkla pussel med 3-4 bitar och räkna små mängder. Hen klarar enkla instruktioner i två steg, till exempel: ”Ta dina skor och ställ dem vid dörren.” Fantasileken blir också rikare i den här åldern: barnet leker kök, sjukhus och affär med sina leksaker. Stöd den kognitiva utvecklingen genom att svara tålmodigt och enkelt på barnets frågor, läsa böcker tillsammans och avsätta tid för pussel, klossar och att rita. Skapa också tillfällen att lära i vardagen, till exempel genom att räkna frukter i affären eller sortera kläder efter färg. Begränsa skärmtiden: WHO rekommenderar inte mer än 1 timmes skärmtid per dag för barn i åldern 3-4 år. Kom ihåg att varje barn utvecklas i sin egen takt.' WHERE day_number = 1099 AND is_active AND md5(coalesce(info,'')) = '70c58295de04e311d1d3a30bfa3acc05' AND md5(coalesce(info_en,'')) = 'cc09dfb04cc3ee8b977e809e0770d4e6' AND md5(coalesce(info_ru,'')) = 'b171c28d6a57f2f7231bbf85e8696f15' AND md5(coalesce(info_tr,'')) = '760ed4dd2d122155ed2151752a62dce3' AND md5(coalesce(info_kk,'')) = '095216912ed123d273600140fed2eaa1' AND md5(coalesce(info_de,'')) = '0eac0ae3a440d14f2a1815c6a3df943b' AND md5(coalesce(info_ar,'')) = '986efa00a4dbcef99f2db58272a5845d' AND md5(coalesce(info_uz,'')) = 'cb555e73f3e7bbdf19162229f8a32244' AND md5(coalesce(info_ka,'')) = '78f344072002bdb95bfdaf340db8b6e1' AND md5(coalesce(info_zh,'')) = '86ee6040d434bd440abb43b29bf499fb' AND md5(coalesce(info_id,'')) = 'c1ef1ab3a8a9efc38b9edb9c702589a7' AND md5(coalesce(info_fr,'')) = 'c158525b57736637b493c8dc9a659760' AND md5(coalesce(info_es,'')) = '8140608a0a49cb33a25b94a8e8369bf9' AND md5(coalesce(info_pt,'')) = '3fd42b14eb647c4a1d3cd9f717e35ef4' AND md5(coalesce(info_vi,'')) = 'cff3d0251f879369e961f66e9ede79a5' AND md5(coalesce(info_hi,'')) = '6437fdbccc4be007b61f170007615009' AND md5(coalesce(info_ja,'')) = 'dde3d491536121e187edbc0024c08923' AND md5(coalesce(info_ko,'')) = '814180d292446b8db0bfba6bb8c9bc36' AND md5(coalesce(info_pl,'')) = '79111f026aec551693f4fc47661bfe76' AND md5(coalesce(info_nl,'')) = '4421c1fd12f7b778a10b962f93450353' AND md5(coalesce(info_sv,'')) = 'a07454b2bb340d3ad4e996c3d9ad59b2';
UPDATE public.baby_daily_info SET info = '3 yaşına çatan övladınızın böyüməsi ilk illərə nisbətən yavaşlayıb. ÜST-ün böyümə standartlarına görə 3 yaşlı oğlan uşaqlarının orta çəkisi təxminən 14,3 kq, qızlarınkı isə 13,9 kq-dır. Normal hesab olunan aralıq (3-97-ci persentil) oğlanlarda təxminən 11,4-18 kq, qızlarda 11-17,8 kq-dır. Orta boy oğlanlarda təxminən 96 sm, qızlarda 95 sm-dir; normal aralıq oğlanlarda 89-103 sm, qızlarda 88-102 sm arasında dəyişir. Bu yaşdan sonra uşaqlar adətən ildə 2 kq ətrafında çəki alır və 6-8 sm boy atır. Tək bir ölçüdən çox, böyümə əyrisinin zamanla necə getdiyi vacibdir. Övladınızın boy və çəkisini Anacan-dakı böyümə qrafikində qeyd edərək ÜST normaları ilə müqayisə edə bilərsiniz. Ölçüləri uzun müddət eyni persentil xətti boyunca gedirsə, narahat olmağa ehtiyac yoxdur. Çəki və ya boy artımı birdən dayanırsa və ya persentil xətlərini kəskin keçirsə, uşaq həkimi ilə məsləhətləşin.', info_en = 'Now that your child is 3, their growth has slowed compared to the first years. According to the WHO growth standards, the average weight of 3-year-old boys is about 14.3 kg, and of girls 13.9 kg. The range considered normal (3rd-97th percentile) is about 11.4-18 kg for boys and 11-17.8 kg for girls. Average height is about 96 cm for boys and 95 cm for girls; the normal range is 89-103 cm for boys and 88-102 cm for girls. From this age on, children usually gain around 2 kg and grow 6-8 cm per year. Rather than any single measurement, what matters is how the growth curve progresses over time. You can record your child''s height and weight on the growth chart in Anacan and compare them with WHO standards. If the measurements follow the same percentile line over a long period, there is no need to worry. If weight or height gain suddenly stops or sharply crosses percentile lines, consult a pediatrician.', info_ru = 'К 3 годам рост вашего ребёнка замедлился по сравнению с первыми годами жизни. Согласно стандартам роста ВОЗ, средний вес мальчиков в 3 года составляет около 14,3 кг, девочек 13,9 кг. Нормальный диапазон (3-97-й перцентиль) у мальчиков составляет примерно 11,4-18 кг, у девочек 11-17,8 кг. Средний рост мальчиков около 96 см, девочек 95 см; нормальный диапазон у мальчиков 89-103 см, у девочек 88-102 см. После этого возраста дети обычно прибавляют около 2 кг веса и вырастают на 6-8 см в год. Важнее не отдельное измерение, а то, как кривая роста меняется со временем. Вы можете отмечать рост и вес ребёнка на графике роста в Anacan и сравнивать их с нормами ВОЗ. Если показатели длительное время идут вдоль одной и той же перцентильной линии, беспокоиться не о чем. Если прибавка веса или роста внезапно останавливается или показатели резко пересекают перцентильные линии, проконсультируйтесь с педиатром.', info_tr = '3 yaşına gelen çocuğunuzun büyümesi ilk yıllara göre yavaşlamıştır. DSÖ büyüme standartlarına göre 3 yaşındaki erkek çocukların ortalama kilosu yaklaşık 14,3 kg, kız çocuklarınınki ise 13,9 kg''dır. Normal kabul edilen aralık (3-97. persentil) erkeklerde yaklaşık 11,4-18 kg, kızlarda 11-17,8 kg''dır. Ortalama boy erkeklerde yaklaşık 96 cm, kızlarda 95 cm''dir; normal aralık erkeklerde 89-103 cm, kızlarda 88-102 cm arasında değişir. Bu yaştan sonra çocuklar genellikle yılda 2 kg civarında kilo alır ve 6-8 cm uzar. Tek bir ölçümden çok, büyüme eğrisinin zaman içinde nasıl ilerlediği önemlidir. Çocuğunuzun boyunu ve kilosunu Anacan''daki büyüme grafiğine kaydederek DSÖ normlarıyla karşılaştırabilirsiniz. Ölçümler uzun süre aynı persentil çizgisi boyunca ilerliyorsa endişelenmenize gerek yoktur. Kilo veya boy artışı aniden duruyorsa ya da ölçümler persentil çizgilerini belirgin şekilde kesiyorsa çocuk doktorunuza danışın.', info_kk = '3 жасқа толған балаңыздың өсуі алғашқы жылдармен салыстырғанда баяулады. ДДСҰ өсу стандарттарына сәйкес 3 жастағы ұл балалардың орташа салмағы шамамен 14,3 кг, қыздардікі 13,9 кг. Қалыпты деп саналатын аралық (3-97-перцентиль) ұлдарда шамамен 11,4-18 кг, қыздарда 11-17,8 кг. Орташа бой ұлдарда шамамен 96 см, қыздарда 95 см; қалыпты аралық ұлдарда 89-103 см, қыздарда 88-102 см аралығында болады. Осы жастан кейін балалар әдетте жылына шамамен 2 кг салмақ қосып, 6-8 см өседі. Жеке бір өлшемнен гөрі өсу қисығының уақыт өте келе қалай өзгеретіні маңыздырақ. Балаңыздың бойы мен салмағын Anacan-дағы өсу графигіне белгілеп, ДДСҰ нормаларымен салыстыра аласыз. Егер өлшемдер ұзақ уақыт бойы бір перцентиль сызығымен жүрсе, алаңдауға негіз жоқ. Егер салмақ немесе бой өсуі кенеттен тоқтаса немесе өлшемдер перцентиль сызықтарын күрт қиып өтсе, балалар дәрігерімен кеңесіңіз.', info_de = 'Mit 3 Jahren wächst dein Kind langsamer als in den ersten Lebensjahren. Laut den Wachstumsstandards der WHO wiegen 3-jährige Jungen im Durchschnitt etwa 14,3 kg, Mädchen 13,9 kg. Der als normal geltende Bereich (3.-97. Perzentile) liegt bei Jungen bei etwa 11,4-18 kg, bei Mädchen bei 11-17,8 kg. Die durchschnittliche Körpergröße beträgt bei Jungen etwa 96 cm, bei Mädchen 95 cm; der Normalbereich reicht bei Jungen von 89-103 cm, bei Mädchen von 88-102 cm. Ab diesem Alter nehmen Kinder in der Regel etwa 2 kg pro Jahr zu und wachsen 6-8 cm. Wichtiger als eine einzelne Messung ist, wie die Wachstumskurve im Laufe der Zeit verläuft. Du kannst Größe und Gewicht deines Kindes in der Wachstumskurve in Anacan eintragen und mit den WHO-Werten vergleichen. Wenn die Messwerte über längere Zeit entlang derselben Perzentilenlinie verlaufen, musst du dir keine Sorgen machen. Wenn die Gewichts- oder Größenzunahme plötzlich stoppt oder die Werte die Perzentilenlinien deutlich kreuzen, sprich mit deiner Kinderärztin oder deinem Kinderarzt.', info_ar = 'تباطأ نمو طفلكِ بعد بلوغه 3 سنوات مقارنةً بالسنوات الأولى. ووفقًا لمعايير النمو الصادرة عن منظمة الصحة العالمية، يبلغ متوسط وزن الأولاد في عمر 3 سنوات نحو 14.3 كغ، والبنات 13.9 كغ. ويتراوح النطاق الذي يُعدّ طبيعيًا (المئين 3-97) لدى الأولاد بين 11.4-18 كغ تقريبًا، ولدى البنات بين 11-17.8 كغ. أما متوسط الطول فيبلغ نحو 96 سم لدى الأولاد و95 سم لدى البنات، ويتراوح النطاق الطبيعي بين 89-103 سم لدى الأولاد و88-102 سم لدى البنات. وبعد هذا العمر، يكتسب الأطفال عادةً نحو 2 كغ من الوزن سنويًا ويزداد طولهم 6-8 سم. والأهم من أي قياس منفرد هو مسار منحنى النمو مع مرور الوقت. ويمكنكِ تسجيل طول طفلكِ ووزنه في مخطط النمو في Anacan ومقارنتهما بمعايير منظمة الصحة العالمية. وإذا استمرت القياسات لفترة طويلة على خط المئين نفسه، فلا داعي للقلق. أما إذا توقف اكتساب الوزن أو الطول فجأة، أو عبرت القياسات خطوط المئين بشكل حاد، فاستشيري طبيب الأطفال.', info_uz = '3 yoshga to‘lgan farzandingizning o‘sishi dastlabki yillarga nisbatan sekinlashgan. JSSTning o‘sish standartlariga ko‘ra, 3 yoshli o‘g‘il bolalarning o‘rtacha vazni taxminan 14,3 kg, qizlarniki esa 13,9 kg. Me’yoriy hisoblanadigan oraliq (3-97-persentil) o‘g‘il bolalarda taxminan 11,4-18 kg, qizlarda 11-17,8 kg. O‘rtacha bo‘y o‘g‘il bolalarda taxminan 96 sm, qizlarda 95 sm; me’yoriy oraliq o‘g‘il bolalarda 89-103 sm, qizlarda 88-102 sm orasida bo‘ladi. Bu yoshdan keyin bolalar odatda yiliga 2 kg atrofida vazn qo‘shadi va 6-8 sm o‘sadi. Bitta o‘lchovdan ko‘ra, o‘sish egri chizig‘ining vaqt o‘tishi bilan qanday borayotgani muhimroq. Farzandingizning bo‘yi va vaznini Anacan ilovasidagi o‘sish grafigiga kiritib, JSST me’yorlari bilan solishtirishingiz mumkin. Agar o‘lchovlar uzoq vaqt davomida bir xil persentil chizig‘i bo‘ylab borsa, xavotirlanishga hojat yo‘q. Agar vazn yoki bo‘y o‘sishi birdan to‘xtasa yoki persentil chiziqlarini keskin kesib o‘tsa, pediatr bilan maslahatlashing.', info_ka = '3 წელს მიღწეული ბავშვის ზრდა პირველ წლებთან შედარებით შენელდა. ჯანმოს ზრდის სტანდარტების მიხედვით, 3 წლის ბიჭების საშუალო წონა დაახლოებით 14,3 კგ-ია, გოგონებისა კი 13,9 კგ. ნორმად მიჩნეული დიაპაზონი (3-97-ე პერცენტილი) ბიჭებში დაახლოებით 11,4-18 კგ-ია, გოგონებში 11-17,8 კგ. საშუალო სიმაღლე ბიჭებში დაახლოებით 96 სმ-ია, გოგონებში 95 სმ; ნორმალური დიაპაზონი ბიჭებში 89-103 სმ-ის, გოგონებში კი 88-102 სმ-ის ფარგლებში მერყეობს. ამ ასაკის შემდეგ ბავშვები, როგორც წესი, წელიწადში დაახლოებით 2 კგ-ს იმატებენ და 6-8 სმ-ით იზრდებიან. ერთ ცალკეულ გაზომვაზე მეტად მნიშვნელოვანია, როგორ მიდის ზრდის მრუდი დროთა განმავლობაში. შეგიძლიათ ბავშვის სიმაღლე და წონა Anacan-ის ზრდის გრაფიკში აღნიშნოთ და ჯანმოს ნორმებს შეადაროთ. თუ გაზომვები დიდი ხნის განმავლობაში ერთი და იმავე პერცენტილის ხაზის გასწვრივ მიდის, შეშფოთების საფუძველი არ არის. თუ წონის ან სიმაღლის მატება მოულოდნელად შეჩერდა ან გაზომვები პერცენტილის ხაზებს მკვეთრად კვეთს, მიმართეთ პედიატრს.', info_zh = '满3岁后，孩子的生长速度比最初几年慢了下来。根据世界卫生组织的儿童生长标准，3岁男孩的平均体重约为14.3 kg，女孩约为13.9 kg。被视为正常的范围（第3-97百分位）男孩约为11.4-18 kg，女孩约为11-17.8 kg。平均身高男孩约为96 cm，女孩约为95 cm；正常范围男孩在89-103 cm之间，女孩在88-102 cm之间。从这个年龄起，孩子通常每年体重增加约2 kg，身高增长6-8 cm。与单次测量结果相比，更重要的是生长曲线随时间的变化趋势。您可以在 Anacan 的生长曲线图中记录孩子的身高和体重，并与世界卫生组织的标准进行比较。如果各项测量值长期沿着同一条百分位线发展，就无需担心。如果体重或身高突然停止增长，或者大幅跨越百分位线，请咨询儿科医生。', info_id = 'Pada usia 3 tahun, pertumbuhan anak Anda melambat dibandingkan tahun-tahun pertamanya. Menurut standar pertumbuhan WHO, berat badan rata-rata anak laki-laki usia 3 tahun sekitar 14,3 kg, sedangkan anak perempuan 13,9 kg. Rentang yang dianggap normal (persentil 3-97) adalah sekitar 11,4-18 kg pada anak laki-laki dan 11-17,8 kg pada anak perempuan. Tinggi badan rata-rata sekitar 96 cm pada anak laki-laki dan 95 cm pada anak perempuan; rentang normalnya 89-103 cm pada anak laki-laki dan 88-102 cm pada anak perempuan. Setelah usia ini, berat badan anak biasanya bertambah sekitar 2 kg dan tinggi badannya bertambah 6-8 cm per tahun. Yang lebih penting dari satu kali pengukuran adalah bagaimana kurva pertumbuhan berjalan dari waktu ke waktu. Anda dapat mencatat tinggi dan berat badan anak di grafik pertumbuhan Anacan untuk membandingkannya dengan standar WHO. Jika hasil pengukurannya mengikuti garis persentil yang sama dalam jangka panjang, Anda tidak perlu khawatir. Jika pertambahan berat atau tinggi badan tiba-tiba berhenti atau memotong garis persentil secara tajam, konsultasikan dengan dokter anak.', info_fr = 'Votre enfant a 3 ans et sa croissance a ralenti par rapport aux premières années. Selon les normes de croissance de l’OMS, le poids moyen des garçons de 3 ans est d’environ 14,3 kg, et celui des filles de 13,9 kg. La fourchette considérée comme normale (du 3e au 97e percentile) est d’environ 11,4-18 kg chez les garçons et de 11-17,8 kg chez les filles. La taille moyenne est d’environ 96 cm chez les garçons et de 95 cm chez les filles ; la fourchette normale va de 89-103 cm chez les garçons et de 88-102 cm chez les filles. Après cet âge, les enfants prennent généralement environ 2 kg et grandissent de 6-8 cm par an. Plus qu’une mesure isolée, c’est l’évolution de la courbe de croissance dans le temps qui compte. Vous pouvez noter la taille et le poids de votre enfant sur la courbe de croissance d’Anacan pour les comparer aux normes de l’OMS. Si les mesures suivent la même ligne de percentile sur une longue période, il n’y a pas lieu de s’inquiéter. Si la prise de poids ou de taille s’arrête soudainement ou si les mesures croisent nettement les lignes de percentile, consultez votre pédiatre.', info_es = 'Tu peque ya tiene 3 años y su crecimiento se ha ralentizado en comparación con los primeros años. Según los patrones de crecimiento de la OMS, el peso medio de los niños de 3 años es de aproximadamente 14,3 kg y el de las niñas, de 13,9 kg. El rango considerado normal (percentiles 3-97) es de aproximadamente 11,4-18 kg en los niños y 11-17,8 kg en las niñas. La estatura media es de unos 96 cm en los niños y 95 cm en las niñas; el rango normal varía entre 89-103 cm en los niños y 88-102 cm en las niñas. A partir de esta edad, los niños suelen ganar unos 2 kg y crecer 6-8 cm al año. Más que una medición aislada, lo importante es cómo evoluciona la curva de crecimiento con el tiempo. Puedes registrar la estatura y el peso de tu peque en la gráfica de crecimiento de Anacan y compararlos con los patrones de la OMS. Si las mediciones siguen la misma línea de percentil durante mucho tiempo, no hay motivo de preocupación. Si el aumento de peso o de estatura se detiene de repente o las mediciones cruzan bruscamente las líneas de percentil, consulta con el pediatra.', info_pt = 'Aos 3 anos, o crescimento da criança abrandou em comparação com os primeiros anos. Segundo os padrões de crescimento da OMS, o peso médio dos rapazes de 3 anos é de cerca de 14,3 kg e o das raparigas de 13,9 kg. O intervalo considerado normal (percentis 3-97) é de cerca de 11,4-18 kg nos rapazes e 11-17,8 kg nas raparigas. A altura média é de cerca de 96 cm nos rapazes e 95 cm nas raparigas; o intervalo normal varia entre 89-103 cm nos rapazes e 88-102 cm nas raparigas. A partir desta idade, as crianças costumam ganhar cerca de 2 kg e crescer 6-8 cm por ano. Mais do que uma medição isolada, o importante é a evolução da curva de crescimento ao longo do tempo. Pode registar a altura e o peso da criança no gráfico de crescimento da Anacan e compará-los com os padrões da OMS. Se as medições seguirem a mesma linha de percentil durante muito tempo, não há motivo para preocupação. Se o aumento de peso ou de altura parar de repente ou se as medições cruzarem acentuadamente as linhas de percentil, consulte o pediatra.', info_vi = 'Khi con lên 3 tuổi, tốc độ tăng trưởng đã chậm lại so với những năm đầu. Theo tiêu chuẩn tăng trưởng của WHO, cân nặng trung bình của bé trai 3 tuổi là khoảng 14,3 kg, còn bé gái là 13,9 kg. Khoảng được coi là bình thường (bách phân vị thứ 3-97) ở bé trai là khoảng 11,4-18 kg, ở bé gái là 11-17,8 kg. Chiều cao trung bình của bé trai là khoảng 96 cm, bé gái là 95 cm; khoảng bình thường dao động từ 89-103 cm ở bé trai và 88-102 cm ở bé gái. Sau độ tuổi này, trẻ thường tăng khoảng 2 kg và cao thêm 6-8 cm mỗi năm. Điều quan trọng không phải là một lần đo riêng lẻ, mà là đường tăng trưởng của con thay đổi như thế nào theo thời gian. Bạn có thể ghi lại chiều cao và cân nặng của con vào biểu đồ tăng trưởng trong Anacan để so sánh với chuẩn của WHO. Nếu các số đo của con đi theo cùng một đường bách phân vị trong thời gian dài thì bạn không cần lo lắng. Nếu cân nặng hoặc chiều cao của con đột ngột ngừng tăng hoặc cắt ngang các đường bách phân vị một cách rõ rệt, bạn hãy tham khảo ý kiến bác sĩ nhi khoa.', info_hi = '3 साल का होने पर आपके बच्चे की बढ़त शुरुआती वर्षों की तुलना में धीमी हो जाती है। विश्व स्वास्थ्य संगठन (WHO) के विकास मानकों के अनुसार, 3 साल के लड़कों का औसत वज़न लगभग 14.3 किग्रा और लड़कियों का 13.9 किग्रा होता है। सामान्य मानी जाने वाली सीमा (3-97वाँ परसेंटाइल) लड़कों में लगभग 11.4-18 किग्रा और लड़कियों में 11-17.8 किग्रा है। औसत लंबाई लड़कों में लगभग 96 सेमी और लड़कियों में 95 सेमी होती है; सामान्य सीमा लड़कों में 89-103 सेमी और लड़कियों में 88-102 सेमी के बीच रहती है। इस उम्र के बाद बच्चे आमतौर पर हर साल लगभग 2 किग्रा वज़न बढ़ाते हैं और 6-8 सेमी लंबे होते हैं। किसी एक माप से ज़्यादा ज़रूरी यह है कि समय के साथ विकास वक्र किस तरह आगे बढ़ रहा है। आप Anacan के ग्रोथ चार्ट में अपने बच्चे की लंबाई और वज़न दर्ज करके उनकी तुलना WHO मानकों से कर सकते हैं। अगर माप लंबे समय तक एक ही परसेंटाइल रेखा के साथ चल रहे हैं, तो चिंता की कोई ज़रूरत नहीं है। अगर वज़न या लंबाई का बढ़ना अचानक रुक जाए या माप परसेंटाइल रेखाओं को तेज़ी से पार करें, तो शिशु रोग विशेषज्ञ से सलाह लें।', info_ja = '3歳を迎えたお子さんの成長は、最初の数年に比べてゆるやかになっています。世界保健機関（WHO）の成長基準によると、3歳の男の子の平均体重は約14.3kg、女の子は13.9kgです。正常とされる範囲（3-97パーセンタイル）は、男の子で約11.4-18kg、女の子で11-17.8kgです。平均身長は男の子で約96cm、女の子で95cmで、正常範囲は男の子で89-103cm、女の子で88-102cmです。この年齢以降、子どもは通常、1年に体重が2kgほど増え、身長が6-8cm伸びます。1回の測定値よりも、成長曲線が時間とともにどのように推移しているかが大切です。Anacanの成長グラフにお子さんの身長と体重を記録して、WHOの基準と比較することができます。測定値が長期間同じパーセンタイル曲線に沿っていれば、心配はいりません。体重や身長の増加が急に止まったり、パーセンタイル曲線を大きく横切ったりする場合は、小児科医に相談しましょう。', info_ko = '3세가 된 아이의 성장은 처음 몇 년에 비해 느려졌어요. 세계보건기구(WHO) 성장 기준에 따르면 3세 남아의 평균 체중은 약 14.3kg, 여아는 13.9kg이에요. 정상으로 여겨지는 범위(3-97백분위수)는 남아가 약 11.4-18kg, 여아가 11-17.8kg이에요. 평균 키는 남아가 약 96cm, 여아가 95cm이고, 정상 범위는 남아 89-103cm, 여아 88-102cm 사이예요. 이 나이 이후 아이들은 보통 1년에 체중이 2kg 정도 늘고 키가 6-8cm 자라요. 한 번의 측정값보다 성장 곡선이 시간에 따라 어떻게 이어지는지가 중요해요. Anacan의 성장 그래프에 아이의 키와 체중을 기록하고 WHO 기준과 비교해 볼 수 있어요. 측정값이 오랫동안 같은 백분위수 선을 따라간다면 걱정할 필요가 없어요. 체중이나 키의 증가가 갑자기 멈추거나 백분위수 선을 급격히 넘나든다면 소아청소년과 의사와 상담하세요.', info_pl = 'Twoje dziecko kończy 3 lata, a jego wzrost i przybieranie na wadze zwolniły w porównaniu z pierwszymi latami. Według siatek centylowych WHO średnia masa ciała trzyletnich chłopców wynosi około 14,3 kg, a dziewczynek 13,9 kg. Zakres uznawany za prawidłowy (3-97 centyl) to u chłopców około 11,4-18 kg, a u dziewczynek 11-17,8 kg. Średni wzrost wynosi u chłopców około 96 cm, a u dziewczynek 95 cm; prawidłowy zakres to u chłopców 89-103 cm, a u dziewczynek 88-102 cm. Po tym wieku dzieci zwykle przybierają na wadze około 2 kg rocznie i rosną o 6-8 cm. Ważniejszy od pojedynczego pomiaru jest przebieg krzywej wzrostu w czasie. Możesz zapisywać wzrost i wagę dziecka na wykresie wzrostu w Anacan i porównywać je z normami WHO. Jeśli pomiary przez dłuższy czas biegną wzdłuż tego samego centyla, nie ma powodu do niepokoju. Jeśli przyrost masy ciała lub wzrostu nagle się zatrzyma albo pomiary gwałtownie przecinają linie centylowe, skonsultuj się z pediatrą.', info_nl = 'Nu je kind 3 jaar is, is de groei vertraagd vergeleken met de eerste jaren. Volgens de groeistandaarden van de WHO is het gemiddelde gewicht van jongens van 3 jaar ongeveer 14,3 kg en van meisjes 13,9 kg. Het bereik dat als normaal geldt (3e-97e percentiel) is bij jongens ongeveer 11,4-18 kg en bij meisjes 11-17,8 kg. De gemiddelde lengte is bij jongens ongeveer 96 cm en bij meisjes 95 cm; het normale bereik ligt bij jongens tussen 89-103 cm en bij meisjes tussen 88-102 cm. Na deze leeftijd komen kinderen meestal ongeveer 2 kg per jaar aan en groeien ze 6-8 cm. Belangrijker dan één enkele meting is hoe de groeicurve zich in de loop van de tijd ontwikkelt. Je kunt de lengte en het gewicht van je kind bijhouden in de groeicurve in Anacan en vergelijken met de WHO-normen. Volgen de metingen lange tijd dezelfde percentiellijn, dan hoef je je geen zorgen te maken. Stopt de groei in gewicht of lengte plotseling of kruisen de metingen sterk de percentiellijnen? Overleg dan met de kinderarts.', info_sv = 'Nu när ditt barn har fyllt 3 år har tillväxten saktat in jämfört med de första åren. Enligt WHO:s tillväxtstandarder är medelvikten för 3-åriga pojkar cirka 14,3 kg och för flickor 13,9 kg. Det normala intervallet (3:e-97:e percentilen) är cirka 11,4-18 kg för pojkar och 11-17,8 kg för flickor. Medellängden är cirka 96 cm för pojkar och 95 cm för flickor; det normala intervallet ligger på 89-103 cm för pojkar och 88-102 cm för flickor. Efter den här åldern ökar barn vanligtvis cirka 2 kg i vikt och växer 6-8 cm per år. Hur tillväxtkurvan utvecklas över tid är viktigare än en enskild mätning. Du kan föra in ditt barns längd och vikt i tillväxtdiagrammet i Anacan och jämföra dem med WHO:s normer. Om måtten följer samma percentilkurva under lång tid finns det ingen anledning till oro. Om vikt- eller längdökningen plötsligt avstannar eller om måtten tydligt korsar percentilkurvorna, rådgör med barnläkaren.' WHERE day_number = 1100 AND is_active AND md5(coalesce(info,'')) = '290fe263aa2eb34a0bfffea43f13bf33' AND md5(coalesce(info_en,'')) = 'e1fb26bdba69b1f732cf53537dbf5d96' AND md5(coalesce(info_ru,'')) = 'd451b5229fa9c0fe6efc706cd28b07d4' AND md5(coalesce(info_tr,'')) = '282f182810145c43808f9d68d70ff446' AND md5(coalesce(info_kk,'')) = 'd33bb863fe0345c57a049dbbaf0cebe1' AND md5(coalesce(info_de,'')) = 'aba347aa034a1fcd7a93a3375739c351' AND md5(coalesce(info_ar,'')) = 'ce9b20ad40594e683d35ca02c4b428ab' AND md5(coalesce(info_uz,'')) = 'fbd13e8c42fe50c31de5974eac8a878e' AND md5(coalesce(info_ka,'')) = '85acb0e5ce8d44f00cc383a00f9f7195' AND md5(coalesce(info_zh,'')) = '56c025f0471a5b542704dd25127d17bf' AND md5(coalesce(info_id,'')) = '4ca875bc11c287fc8aa6d51d1d3aac00' AND md5(coalesce(info_fr,'')) = 'c37e1d22791c1761ef9300267d3758fd' AND md5(coalesce(info_es,'')) = 'be33e699dd29a345b0f333d779fad8a5' AND md5(coalesce(info_pt,'')) = '708212b5ad307786b74d8d16809d27fa' AND md5(coalesce(info_vi,'')) = '4126354bb354ebcfb3670afda03bf0a6' AND md5(coalesce(info_hi,'')) = 'ae1bbb1d128cf0d06605235be6fe96a1' AND md5(coalesce(info_ja,'')) = 'e07337da53f9785ec2ee942fd3d3e91a' AND md5(coalesce(info_ko,'')) = '556eed5ed1c5d76c149eb9fb5aeb6318' AND md5(coalesce(info_pl,'')) = '03dba71e8fbeccc96c552093a9cca059' AND md5(coalesce(info_nl,'')) = '8f683970abf5c086ca43b927045a7f70' AND md5(coalesce(info_sv,'')) = '165bef1a93627ac12fbe06f75b01ea59';
UPDATE public.baby_daily_info SET info_en = 'From this month on, the lower limit of your baby''s head circumference is 41 cm and the upper limit is 47 cm. The average head circumference of an 8-month-old baby is about 44 cm. Since head circumference growth is an indicator of brain development, it should be measured regularly. A baby in their 8th month can be between 64.5 cm and 75 cm long. You may also notice that your baby''s fontanelle is starting to firm up during this period. The fontanelle, which is usually expected to close between 12-18 months, may be seen starting to close in the 8th month in some babies. As long as brain development continues, this is considered physiologically normal and there is no need to worry.', info_zh = '从这个月起，宝宝头围的下限为41 cm，上限为47 cm。8个月大的宝宝平均头围约为44 cm。头围的增长是大脑发育的指标，因此应定期测量。第8个月的宝宝身长可能在64.5 cm到75 cm之间。在这个阶段，你还可能会发现宝宝的囟门开始变硬。囟门通常在12-18个月之间闭合，但有些宝宝的囟门在第8个月时就可能开始闭合。只要大脑仍在继续发育，这种情况在生理上就被视为正常，无需担心。', info_id = 'Mulai bulan ini, batas bawah lingkar kepala bayi Anda adalah 41 cm dan batas atasnya 47 cm. Lingkar kepala rata-rata bayi usia 8 bulan sekitar 44 cm. Karena pertumbuhan lingkar kepala merupakan indikator perkembangan otak, lingkar kepala perlu diukur secara rutin. Pada bulan ke-8, panjang badan bayi dapat berkisar antara 64,5 cm dan 75 cm. Pada masa ini, Anda mungkin juga melihat ubun-ubun bayi mulai mengeras. Ubun-ubun yang biasanya diperkirakan menutup pada usia 12-18 bulan dapat mulai menutup pada bulan ke-8 pada sebagian bayi. Jika perkembangan otaknya terus berlangsung, kondisi ini dianggap normal secara fisiologis dan Anda tidak perlu khawatir.', info_fr = 'À partir de ce mois, la limite inférieure du périmètre crânien de votre bébé est de 41 cm et la limite supérieure de 47 cm. À 8 mois, le périmètre crânien moyen d’un bébé est d’environ 44 cm. La croissance du périmètre crânien étant un indicateur du développement cérébral, il doit être mesuré régulièrement. Au cours de son 8e mois, la taille de votre bébé peut se situer entre 64,5 cm et 75 cm. Vous remarquerez peut-être aussi que la fontanelle de votre bébé commence à durcir pendant cette période. Chez certains bébés, la fontanelle, dont la fermeture est généralement attendue entre 12-18 mois, peut commencer à se refermer dès le 8e mois. Si le développement cérébral se poursuit, cette situation est considérée comme physiologiquement normale et il n’y a pas lieu de s’inquiéter.', info_es = 'A partir de este mes, el límite inferior del perímetro cefálico de tu bebé es de 41 cm y el superior, de 47 cm. A los 8 meses, el perímetro cefálico medio es de aproximadamente 44 cm. Como el crecimiento del perímetro cefálico es un indicador del desarrollo cerebral, debe medirse con regularidad. Durante su 8.º mes, la longitud de tu bebé puede estar entre 64,5 cm y 75 cm. En esta etapa también puedes notar que la fontanela de tu bebé empieza a endurecerse. En algunos bebés, la fontanela, que normalmente se cierra entre los 12-18 meses, puede empezar a cerrarse ya en el 8.º mes. Si el desarrollo cerebral continúa, esto se considera fisiológicamente normal y no hay motivo de preocupación.', info_pt = 'A partir deste mês, o limite inferior do perímetro cefálico do seu bebé é de 41 cm e o limite superior de 47 cm. Aos 8 meses, o perímetro cefálico médio de um bebé é de cerca de 44 cm. Como o crescimento do perímetro cefálico é um indicador do desenvolvimento cerebral, deve ser medido regularmente. No 8.º mês, o comprimento do bebé pode situar-se entre 64,5 cm e 75 cm. Nesta fase, poderá também notar que a fontanela do seu bebé começa a endurecer. Em alguns bebés, a fontanela, cujo encerramento é normalmente esperado entre os 12-18 meses, pode começar a fechar já no 8.º mês. Se o desenvolvimento cerebral continuar, esta situação é considerada fisiologicamente normal e não há motivo para preocupação.', info_vi = 'Từ tháng này, giới hạn dưới của vòng đầu của bé là 41 cm và giới hạn trên là 47 cm. Vòng đầu trung bình của bé 8 tháng tuổi vào khoảng 44 cm. Vì sự phát triển của vòng đầu là chỉ dấu cho sự phát triển của não bộ, bạn nên đo vòng đầu cho bé thường xuyên. Chiều dài của bé trong tháng thứ 8 có thể từ 64,5 cm đến 75 cm. Ngoài ra, trong giai đoạn này bạn có thể thấy thóp của bé bắt đầu cứng lại. Thóp thường được dự kiến sẽ đóng trong khoảng từ 12 đến 18 tháng, nhưng ở một số bé, thóp có thể bắt đầu đóng ngay từ tháng thứ 8. Nếu não bộ của bé vẫn tiếp tục phát triển, hiện tượng này được coi là bình thường về mặt sinh lý và bạn không cần lo lắng.', info_hi = 'इस महीने से आपके शिशु के सिर की परिधि की निचली सीमा 41 सेमी और ऊपरी सीमा 47 सेमी है। 8 महीने के शिशु के सिर की औसत परिधि लगभग 44 सेमी होती है। चूँकि सिर की परिधि का बढ़ना मस्तिष्क के विकास का संकेत है, इसलिए इसे नियमित रूप से मापना चाहिए। 8वें महीने में शिशु की लंबाई 64.5 सेमी से 75 सेमी के बीच हो सकती है। इस दौरान आप यह भी देख सकते हैं कि आपके शिशु का तालू (सिर का नरम हिस्सा) सख्त होने लगा है। तालू आमतौर पर 12 से 18 महीने के बीच बंद होता है, लेकिन कुछ शिशुओं में यह 8वें महीने में ही बंद होना शुरू हो सकता है। अगर मस्तिष्क का विकास जारी है, तो इसे शारीरिक रूप से सामान्य माना जाता है और चिंता करने की कोई ज़रूरत नहीं है।', info_ja = '今月から、赤ちゃんの頭囲の下限は41cm、上限は47cmです。生後8か月の赤ちゃんの平均頭囲は約44cmです。頭囲の成長は脳の発達の指標となるため、定期的に測るようにしましょう。生後8か月目の赤ちゃんの身長は、64.5cmから75cmの間であることが多いです。この時期には、赤ちゃんの大泉門が硬くなり始めていることに気づくかもしれません。通常は12-18か月の間に閉じるとされる大泉門が、8か月目に閉じ始める赤ちゃんもいます。脳の発達が続いていれば、これは生理的に正常な状態とされ、心配する必要はありません。', info_ko = '이번 달부터 아기 머리둘레의 하한은 41cm, 상한은 47cm예요. 생후 8개월 아기의 평균 머리둘레는 약 44cm예요. 머리둘레의 증가는 뇌 발달의 지표이므로 정기적으로 측정해야 해요. 생후 8개월째 아기의 키는 64.5cm에서 75cm 사이일 수 있어요. 또한 이 시기에 아기의 숫구멍(대천문)이 단단해지기 시작하는 것을 볼 수 있어요. 보통 12-18개월 사이에 닫힐 것으로 예상되는 숫구멍이 일부 아기에게서는 8개월째에 닫히기 시작하는 모습이 관찰될 수 있어요. 뇌 발달이 계속 이루어지고 있다면 이는 생리적으로 정상으로 여겨지므로 걱정할 필요가 없어요.', info_pl = 'Od tego miesiąca dolna granica obwodu głowy Twojego dziecka wynosi 41 cm, a górna 47 cm. Średni obwód głowy 8-miesięcznego niemowlęcia to około 44 cm. Ponieważ przyrost obwodu głowy jest wskaźnikiem rozwoju mózgu, należy go regularnie mierzyć. W 8. miesiącu długość ciała niemowlęcia może wynosić od 64,5 cm do 75 cm. W tym okresie możesz też zauważyć, że ciemiączko Twojego dziecka zaczyna twardnieć. Ciemiączko zwykle zamyka się między 12. a 18. miesiącem, jednak u niektórych niemowląt może zacząć się zamykać już w 8. miesiącu. Jeśli mózg nadal prawidłowo się rozwija, uznaje się to za zjawisko fizjologiczne i nie ma powodu do niepokoju.', info_nl = 'Vanaf deze maand ligt de ondergrens van de hoofdomtrek van je baby op 41 cm en de bovengrens op 47 cm. De gemiddelde hoofdomtrek van een baby van 8 maanden is ongeveer 44 cm. Omdat de groei van de hoofdomtrek een aanwijzing is voor de ontwikkeling van de hersenen, is het belangrijk die regelmatig te meten. In de 8e maand kan de lengte van je baby tussen 64,5 cm en 75 cm liggen. Ook kun je in deze periode merken dat de fontanel van je baby harder begint te worden. De fontanel sluit zich meestal tussen 12 en 18 maanden, maar bij sommige baby''s kan deze al in de 8e maand beginnen te sluiten. Als de hersenen zich gewoon verder ontwikkelen, geldt dit als fysiologisch normaal en hoef je je geen zorgen te maken.', info_sv = 'Från och med den här månaden är den nedre gränsen för bebisens huvudomfång 41 cm och den övre gränsen 47 cm. En 8 månader gammal bebis har ett genomsnittligt huvudomfång på cirka 44 cm. Eftersom huvudomfångets tillväxt är en indikator på hjärnans utveckling bör det mätas regelbundet. En bebis i sin 8:e månad kan vara mellan 64,5 cm och 75 cm lång. Under den här perioden kan du också märka att bebisens fontanell börjar bli fastare. Fontanellen förväntas vanligtvis slutas vid 12-18 månaders ålder, men hos vissa bebisar kan man se att den börjar slutas redan i den 8:e månaden. Om hjärnans utveckling fortsätter som den ska anses detta fysiologiskt normalt och det finns ingen anledning till oro.' WHERE day_number = 246 AND is_active AND md5(coalesce(info_en,'')) = '68cbeb74d7b47eb3099f93d40c488d96' AND md5(coalesce(info_zh,'')) = 'f2cbbf6de7d2cfc2966659d96b4b80fb' AND md5(coalesce(info_id,'')) = '6d33ec7f5cd2228b56c4c59f45bbb914' AND md5(coalesce(info_fr,'')) = 'a4878c43000934a54be19f3b1ef25568' AND md5(coalesce(info_es,'')) = 'ed912af0941a3c976f9a5d585d77b14b' AND md5(coalesce(info_pt,'')) = '2fe47ac72861f73e5935dd5cd6bae8c6' AND md5(coalesce(info_vi,'')) = '4697fc71a1f40c0f74788165333f1ec8' AND md5(coalesce(info_hi,'')) = '6610ec20869f8e6f7d000009b08b22a5' AND md5(coalesce(info_ja,'')) = 'b61616b40232f2da79f6e51c0633cfaf' AND md5(coalesce(info_ko,'')) = '36e5b709095ac9f4ce62e284cdef5377' AND md5(coalesce(info_pl,'')) = '909b3388003f4cb4090de07c4840b433' AND md5(coalesce(info_nl,'')) = '41a0c8f1c4872277dae2bc00af9b114d' AND md5(coalesce(info_sv,'')) = '9b57bfb0ce4521cdcbf623b1c54f67df';
UPDATE public.baby_daily_info SET info_en = 'The human brain has two separate regions: the right and left hemispheres. The part that controls the right hand is the left hemisphere of the brain, and the part that controls the left hand is the right hemisphere. At this stage, your baby can most likely use both hands equally. One question many families wonder about is when left- or right-handedness becomes clear. Although there is no exact answer, which hand your baby will use better may only become clear after age 3-4. Still, your baby may already begin to show some signs. For example, turning counterclockwise when they want to turn around, or trying to grab with their left hand when something is handed to them, are among the early signs of left-handedness. Left-handedness is generally a normal, genetically based trait. Apart from rare exceptions, it causes no problems. If you and your partner are both left-handed, the chance of your baby being left-handed is about 50%. If one of you is left-handed, this rate may drop to around 25%. If you think your baby is left-handed, you shouldn''t force them to use their right hand, because this can lead to many problems, especially learning difficulties.', info_zh = '人的大脑分为左、右两个半球。控制右手的是大脑的左半球，控制左手的是大脑的右半球。在这个阶段，宝宝很可能两只手都能同样地使用。很多家庭关心的一个问题是：宝宝是左撇子还是右撇子，什么时候才能确定？这个问题并没有确切的答案，宝宝更擅长使用哪只手，可能要到3-4岁以后才能明确。不过，宝宝现在可能已经开始显露出一些迹象。例如，想转身时按逆时针方向转，别人递东西过来时试图用左手去接，这些都是左撇子的早期迹象。左撇子通常是一种由遗传决定的正常现象。除了极少数例外，它不会带来任何问题。如果你和伴侣都是左撇子，宝宝成为左撇子的概率约为50%。如果你们其中一人是左撇子，这个比例可能会降到25%左右。如果你认为宝宝是左撇子，不要强迫宝宝使用右手，因为这可能会导致许多问题，尤其是学习困难。', info_id = 'Otak manusia terdiri dari dua bagian terpisah, yaitu belahan kanan dan belahan kiri. Bagian yang mengendalikan tangan kanan adalah belahan otak kiri, sedangkan bagian yang mengendalikan tangan kiri adalah belahan otak kanan. Pada tahap ini, bayi Anda kemungkinan besar dapat menggunakan kedua tangannya dengan cara yang sama. Salah satu hal yang membuat banyak keluarga penasaran adalah kapan akan diketahui apakah anak kidal atau tidak. Meskipun tidak ada jawaban pasti untuk pertanyaan ini, tangan mana yang akan lebih terampil digunakan bayi baru dapat dipastikan setelah usia 3-4 tahun. Meski begitu, bayi Anda mungkin sudah mulai menunjukkan beberapa tanda sejak sekarang. Misalnya, berputar berlawanan arah jarum jam saat ingin berbalik, atau mencoba meraih dengan tangan kiri ketika diberi sesuatu, termasuk tanda-tanda awal kidal. Kidal umumnya merupakan kondisi normal yang dipengaruhi faktor genetik. Kecuali dalam kasus yang jarang terjadi, kidal tidak menimbulkan masalah apa pun. Jika Anda dan pasangan sama-sama kidal, kemungkinan bayi Anda kidal sekitar 50%. Jika hanya salah satu dari Anda yang kidal, kemungkinan ini dapat turun hingga 25%. Jika Anda merasa bayi Anda kidal, jangan memaksanya menggunakan tangan kanan, karena hal ini dapat menimbulkan banyak masalah, terutama kesulitan belajar.', info_fr = 'Le cerveau humain se compose de deux régions distinctes : l’hémisphère droit et l’hémisphère gauche. C’est l’hémisphère gauche qui contrôle la main droite, et l’hémisphère droit qui contrôle la main gauche. À ce stade, votre bébé utilise très probablement ses deux mains de la même manière. L’une des questions que se posent souvent les familles est de savoir quand on saura s’il est gaucher ou droitier. Il n’existe pas de réponse précise à cette question, mais la main que votre bébé utilisera le mieux ne pourra se préciser qu’après 3-4 ans. Votre bébé peut néanmoins déjà commencer à donner quelques indices. Par exemple, se tourner dans le sens inverse des aiguilles d’une montre lorsqu’il veut se retourner, ou essayer d’attraper avec la main gauche un objet qu’on lui tend, font partie des signes précoces d’une préférence pour la main gauche. Être gaucher est généralement une particularité normale d’origine génétique. Sauf rares exceptions, cela ne pose aucun problème. Si vous et votre partenaire êtes tous deux gauchers, la probabilité que votre bébé soit gaucher est d’environ 50 %. Si un seul de vous deux est gaucher, ce taux peut descendre jusqu’à 25 %. Si vous pensez que votre bébé est gaucher, ne le forcez pas à utiliser sa main droite. Cela pourrait en effet entraîner de nombreux problèmes, notamment des difficultés d’apprentissage.', info_es = 'El cerebro humano tiene dos regiones separadas: el hemisferio derecho y el izquierdo. La mano derecha está controlada por el hemisferio izquierdo del cerebro, y la mano izquierda, por el hemisferio derecho. En esta etapa, lo más probable es que tu bebé use las dos manos por igual. Una de las dudas más habituales de las familias es cuándo se sabrá si será zurdo o diestro. Aunque no hay una respuesta exacta, la mano que tu bebé usará mejor puede no definirse hasta después de los 3-4 años. Aun así, tu bebé ya puede empezar a dar algunas pistas. Por ejemplo, girar en sentido contrario a las agujas del reloj cuando quiere darse la vuelta o intentar coger con la mano izquierda algo que le ofreces son algunos de los primeros signos de zurdera. Ser zurdo suele ser una condición normal de origen genético. Salvo raras excepciones, no supone ningún problema. Si tu pareja y tú sois zurdos, la probabilidad de que tu bebé también lo sea es de aproximadamente el 50%. Si solo uno de los dos es zurdo, esta probabilidad puede bajar hasta el 25%. Si crees que tu bebé es zurdo, no debes obligarle a usar la mano derecha, ya que esto puede causar muchos problemas, entre ellos dificultades de aprendizaje.', info_pt = 'O cérebro humano tem duas regiões distintas: o hemisfério direito e o hemisfério esquerdo. A mão direita é controlada pelo hemisfério esquerdo do cérebro, e a mão esquerda pelo hemisfério direito. Nesta fase, é muito provável que o seu bebé use as duas mãos da mesma forma. Uma das questões que mais interessam às famílias é saber quando se vai perceber se a criança é canhota ou destra. Embora não exista uma resposta exata, a mão que o bebé vai usar melhor só se poderá definir depois dos 3-4 anos. Ainda assim, o seu bebé pode começar desde já a dar alguns sinais. Por exemplo, rodar no sentido contrário ao dos ponteiros do relógio quando se quer virar ou tentar agarrar com a mão esquerda algo que lhe estendem são alguns dos primeiros sinais de que pode ser canhoto. Ser canhoto é, em geral, uma condição normal de base genética. Salvo raras exceções, não causa qualquer problema. Se o pai e a mãe forem ambos canhotos, a probabilidade de o bebé ser canhoto é de cerca de 50%. Se apenas um dos dois for canhoto, esta percentagem pode descer até 25%. Se acha que o seu bebé é canhoto, não o deve obrigar a usar a mão direita, pois isso pode causar vários problemas, sobretudo dificuldades de aprendizagem.', info_vi = 'Não bộ con người có hai vùng riêng biệt là bán cầu não phải và bán cầu não trái. Phần điều khiển tay phải là bán cầu não trái, còn phần điều khiển tay trái là bán cầu não phải. Ở giai đoạn này, nhiều khả năng bé có thể sử dụng cả hai tay như nhau. Một trong những điều các gia đình quan tâm là khi nào sẽ biết bé thuận tay trái hay tay phải. Dù câu hỏi này không có câu trả lời chính xác, bé sẽ dùng tay nào khéo hơn thường chỉ rõ ràng sau 3-4 tuổi. Tuy vậy, ngay từ bây giờ bé đã có thể bắt đầu cho thấy một vài dấu hiệu. Ví dụ, khi muốn xoay người thì xoay theo chiều ngược kim đồng hồ, hoặc khi bạn đưa cho bé một vật thì bé cố cầm bằng tay trái, đó là những dấu hiệu sớm của việc thuận tay trái. Thuận tay trái nhìn chung là một đặc điểm bình thường có cơ sở di truyền. Ngoại trừ một số rất ít trường hợp, điều này không gây ra vấn đề gì. Nếu cả bạn và người bạn đời đều thuận tay trái, khả năng bé thuận tay trái là khoảng 50%. Nếu chỉ một trong hai người thuận tay trái, tỷ lệ này có thể giảm xuống khoảng 25%. Nếu bạn nghĩ bé thuận tay trái, bạn đừng ép bé dùng tay phải. Bởi vì điều đó có thể gây ra nhiều vấn đề, trước hết là khó khăn trong học tập.', info_hi = 'मानव मस्तिष्क में दो अलग-अलग हिस्से होते हैं: दायाँ और बायाँ गोलार्ध। दाएँ हाथ को नियंत्रित करने वाला हिस्सा मस्तिष्क का बायाँ गोलार्ध है, और बाएँ हाथ को नियंत्रित करने वाला हिस्सा दायाँ गोलार्ध है। इस चरण में आपका शिशु संभवतः दोनों हाथों का एक जैसा उपयोग कर सकता है। परिवारों के मन में अक्सर यह सवाल आता है कि कब पता चलेगा कि बच्चा बाएँ हाथ से काम करेगा या दाएँ हाथ से। हालाँकि इस सवाल का कोई सटीक जवाब नहीं है, लेकिन शिशु किस हाथ का बेहतर उपयोग करेगा, यह आमतौर पर 3-4 साल की उम्र के बाद ही स्पष्ट हो पाता है। फिर भी, आपका शिशु अभी से कुछ संकेत देना शुरू कर सकता है। उदाहरण के लिए, मुड़ना चाहे तो घड़ी की सुई की उल्टी दिशा में मुड़ना, या कोई चीज़ आगे बढ़ाने पर उसे बाएँ हाथ से पकड़ने की कोशिश करना, बाएँ हाथ से काम करने के शुरुआती संकेतों में से हैं। बाएँ हाथ से काम करना आमतौर पर आनुवंशिक आधार वाली एक सामान्य बात है। बहुत कम अपवादों को छोड़कर, इससे कोई समस्या नहीं होती। अगर आप और आपके जीवनसाथी दोनों बाएँ हाथ से काम करते हैं, तो शिशु के बाएँ हाथ वाला होने की संभावना लगभग 50% होती है। अगर आप दोनों में से केवल एक बाएँ हाथ वाला है, तो यह संभावना 25% तक घट सकती है। अगर आपको लगता है कि आपका शिशु बाएँ हाथ वाला है, तो उसे दाएँ हाथ का उपयोग करने के लिए मजबूर न करें। क्योंकि इससे सीखने में कठिनाइयों सहित कई समस्याएँ हो सकती हैं।', info_ja = '人間の脳には、右半球と左半球という2つの領域があります。右手を動かしているのは脳の左半球で、左手を動かしているのは脳の右半球です。この時期の赤ちゃんは、おそらく両手を同じように使えるでしょう。家族が気になることの一つに、左利きか右利きかがいつわかるのかということがあります。この質問にはっきりとした答えはありませんが、赤ちゃんがどちらの手をより上手に使うようになるかは、3-4歳を過ぎてからでないとはっきりしないこともあります。それでも、赤ちゃんは今からいくつかのサインを見せ始めることがあります。たとえば、向きを変えたいときに反時計回りに回る、何かを差し出されたときに左手でつかもうとする、といったことは左利きの早期のサインです。左利きは一般的に、遺伝に基づく正常なものです。ごくまれな例外を除き、何の問題もありません。あなたとパートナーがどちらも左利きの場合、赤ちゃんが左利きになる確率は約50%です。どちらか一方が左利きの場合は、この割合は25%程度まで下がることがあります。赤ちゃんが左利きだと思っても、右手を使うように強制しないでください。学習の困難をはじめ、さまざまな問題につながるおそれがあります。', info_ko = '사람의 뇌는 우반구와 좌반구라는 두 개의 영역으로 나뉘어 있어요. 오른손을 조절하는 부분은 뇌의 좌반구이고, 왼손을 조절하는 부분은 뇌의 우반구예요. 이 시기의 아기는 아마 두 손을 똑같이 사용할 수 있을 거예요. 부모님들이 궁금해하는 것 중 하나는 왼손잡이인지 오른손잡이인지가 언제 드러나는가 하는 점이에요. 이 질문에 정확한 답은 없지만, 아기가 어느 손을 더 잘 쓰게 될지는 3-4세가 지나야 확실해질 수 있어요. 그래도 아기는 지금부터 몇 가지 신호를 보이기 시작할 수 있어요. 예를 들어 몸을 돌리고 싶을 때 시계 반대 방향으로 돌거나, 누군가 무언가를 건넬 때 왼손으로 잡으려고 하는 것은 왼손잡이의 초기 신호예요. 왼손잡이는 일반적으로 유전적 요인에 따른 정상적인 특성이에요. 드문 예외를 제외하면 아무런 문제가 되지 않아요. 부모가 모두 왼손잡이라면 아기가 왼손잡이일 확률은 약 50%예요. 둘 중 한 명이 왼손잡이라면 이 비율은 25% 정도까지 낮아질 수 있어요. 아기가 왼손잡이라고 생각된다면 오른손을 쓰도록 강요하지 마세요. 학습의 어려움을 비롯한 여러 문제를 일으킬 수 있기 때문이에요.', info_pl = 'Ludzki mózg składa się z dwóch odrębnych części: prawej i lewej półkuli. Prawą ręką steruje lewa półkula mózgu, a lewą ręką prawa półkula. Na tym etapie Twoje dziecko najprawdopodobniej posługuje się obiema rękami w podobny sposób. Jedną z kwestii, które interesują rodziców, jest to, kiedy okaże się, czy dziecko będzie leworęczne, czy praworęczne. Choć na to pytanie nie ma jednoznacznej odpowiedzi, to, którą ręką dziecko będzie posługiwać się sprawniej, może się wyjaśnić dopiero po 3-4 roku życia. Mimo to już teraz Twoje dziecko może dawać pewne sygnały. Na przykład obracanie się w kierunku przeciwnym do ruchu wskazówek zegara, gdy chce się odwrócić, czy próby chwytania lewą ręką podawanego przedmiotu należą do wczesnych oznak leworęczności. Leworęczność jest zazwyczaj normalną cechą o podłożu genetycznym. Poza rzadkimi wyjątkami nie stanowi żadnego problemu. Jeśli Ty i Twój partner jesteście leworęczni, prawdopodobieństwo, że dziecko będzie leworęczne, wynosi około 50%. Jeśli leworęczne jest tylko jedno z Was, odsetek ten może spaść do około 25%. Jeśli uważasz, że Twoje dziecko jest leworęczne, nie zmuszaj go do używania prawej ręki. Może to bowiem prowadzić do wielu problemów, przede wszystkim do trudności w nauce.', info_nl = 'Het menselijk brein bestaat uit twee afzonderlijke delen: de rechter- en de linkerhersenhelft. De rechterhand wordt aangestuurd door de linkerhersenhelft en de linkerhand door de rechterhersenhelft. In deze fase gebruikt je baby waarschijnlijk beide handen nog op dezelfde manier. Veel ouders vragen zich af wanneer duidelijk wordt of hun kind links- of rechtshandig is. Hoewel daar geen exact antwoord op is, wordt pas na 3-4 jaar echt duidelijk welke hand je kind het handigst gebruikt. Toch kan je baby nu al enkele signalen geven. Tegen de klok in draaien wanneer je baby zich wil omdraaien, of een aangereikt voorwerp met de linkerhand proberen te pakken, zijn bijvoorbeeld vroege tekenen van linkshandigheid. Linkshandigheid is meestal een normale eigenschap met een genetische basis. Op zeldzame uitzonderingen na veroorzaakt het geen enkel probleem. Als jij en je partner allebei linkshandig zijn, is de kans dat je baby linkshandig is ongeveer 50%. Is maar een van jullie linkshandig, dan kan die kans dalen tot ongeveer 25%. Denk je dat je baby linkshandig is? Dwing je kind dan niet om de rechterhand te gebruiken. Dat kan namelijk tot allerlei problemen leiden, met name leerproblemen.', info_sv = 'Människans hjärna består av två separata delar, den högra och den vänstra hjärnhalvan. Den del som styr höger hand är den vänstra hjärnhalvan, och den del som styr vänster hand är den högra hjärnhalvan. I det här skedet kan din bebis troligen använda båda händerna på samma sätt. En fråga som många familjer funderar på är när det blir tydligt om barnet är vänster- eller högerhänt. Det finns inget exakt svar på den frågan, men vilken hand bebisen kommer att använda bäst kan ofta fastställas först efter 3-4 års ålder. Ändå kan din bebis redan nu börja ge vissa tecken. Att vända sig moturs när hen ska vända sig, eller att försöka ta tag med vänster hand när man räcker fram något, är till exempel tidiga tecken på vänsterhänthet. Vänsterhänthet är i regel ett normalt, genetiskt betingat drag. Med sällsynta undantag orsakar det inga problem. Om både du och din partner är vänsterhänta är sannolikheten att bebisen blir vänsterhänt cirka 50 %. Om en av er är vänsterhänt kan sannolikheten sjunka till omkring 25 %. Om du tror att din bebis är vänsterhänt ska du inte tvinga hen att använda höger hand. Det kan nämligen leda till många problem, inte minst inlärningssvårigheter.' WHERE day_number = 387 AND is_active AND md5(coalesce(info_en,'')) = '6585f53bcf867e8496837332b4277251' AND md5(coalesce(info_zh,'')) = '5cc5b8ad2144591bbac5d995ff505692' AND md5(coalesce(info_id,'')) = 'b61d6edd564df3a0e331867b4b843580' AND md5(coalesce(info_fr,'')) = 'b208c44c1780786897dab2c07020f458' AND md5(coalesce(info_es,'')) = 'abf8cad2a963aaedd764b4d991755e64' AND md5(coalesce(info_pt,'')) = '59022907517f08df9acf1f335868dffa' AND md5(coalesce(info_vi,'')) = '88930c8610a872532b9fc5e77698d169' AND md5(coalesce(info_hi,'')) = '34c3786c2d141e38979f665000b287d5' AND md5(coalesce(info_ja,'')) = 'bac5cbacb905e588f986b005352d3e17' AND md5(coalesce(info_ko,'')) = '8483272a2b16069cc3ac5d36de3fb3bd' AND md5(coalesce(info_pl,'')) = 'ab0b707a6dd3d56be1e4c730b0e2009e' AND md5(coalesce(info_nl,'')) = '382ba276c1756ffc19ff5c37c4f643b4' AND md5(coalesce(info_sv,'')) = '1ad12839c22f1d55e26038349af3cdf1';

